#!/usr/bin/env bun
/**
 * Cline Hook: PostToolUse (TypeScript)
 * Logs tool results with structured output.
 * Copy to ~/.cline/hooks/PostToolUse.ts and chmod +x
 */

interface ToolResult {
	id: string;
	name: string;
	input: Record<string, unknown>;
	output: unknown;
	error: unknown;
	durationMs: number;
}

interface HookEvent {
	hookName: string;
	tool_result: ToolResult;
	postToolUse: {
		toolName: string;
		parameters: Record<string, unknown>;
		result: string;
		success: boolean;
		executionTimeMs: number;
	};
}

interface HookControl {
	context?: string;
	errorMessage?: string;
}

async function getGitBranch(): Promise<string | null> {
	try {
		const proc = Bun.spawn(["git", "branch", "--show-current"]);
		const output = await new Response(proc.stdout).text();
		return output.trim() || null;
	} catch {
		return null;
	}
}

async function main(): Promise<void> {
	let event: HookEvent;

	try {
		const input = await Bun.stdin.text();
		event = JSON.parse(input) as HookEvent;
	} catch (error) {
		const message =
			error instanceof Error ? error.message : "Unknown parse error";
		console.log(
			JSON.stringify({ errorMessage: `Failed to parse: ${message}` }),
		);
		return;
	}

	const toolName = event.tool_result.name;
	const success = event.postToolUse.success;
	const durationMs = event.postToolUse.executionTimeMs;

	// Log result
	const status = success ? "✅" : "❌";
	console.error(`${status} Tool: ${toolName} (${durationMs}ms)`);

	// For run_commands, inject environment context
	if (toolName === "run_commands") {
		const branch = await getGitBranch();
		if (branch) {
			const control: HookControl = {
				context: `Environment: git branch: ${branch}`,
			};
			console.log(JSON.stringify(control));
			return;
		}
	}

	// Return empty control
	console.log(JSON.stringify({}));
}

main().catch((error) => {
	console.error("Hook error:", error);
	process.exit(1);
});

#!/usr/bin/env bun
/**
 * Cline Hook: PreToolUse (TypeScript)
 * Logs and filters tool calls with type safety.
 * Copy to ~/.cline/hooks/PreToolUse.ts and chmod +x
 */

interface ToolCall {
	id: string;
	name: string;
	input: Record<string, unknown>;
}

interface HookEvent {
	hookName: string;
	tool_call: ToolCall;
	preToolUse: {
		toolName: string;
		parameters: Record<string, unknown>;
	};
}

interface HookControl {
	cancel?: boolean;
	review?: boolean;
	context?: string;
	errorMessage?: string;
	overrideInput?: unknown;
}

async function main(): Promise<void> {
	let event: HookEvent;

	try {
		const input = await Bun.stdin.text();
		event = JSON.parse(input) as HookEvent;
	} catch (error) {
		const message =
			error instanceof Error ? error.message : "Unknown parse error";
		console.log(
			JSON.stringify({ errorMessage: `Failed to parse: ${message}` }),
		);
		return;
	}

	const toolName = event.tool_call.name;
	const parameters = event.preToolUse.parameters;

	// Log to stderr
	console.error(`🔧 Tool: ${toolName}`);
	if (Object.keys(parameters).length > 0) {
		const paramStr = Object.entries(parameters)
			.map(([k, v]) => `${k}=${v}`)
			.join(", ");
		console.error(`   Args: ${paramStr}`);
	}

	// Return empty control (allow execution)
	const control: HookControl = {};
	console.log(JSON.stringify(control));
}

main().catch((error) => {
	console.error("Hook error:", error);
	process.exit(1);
});

#!/usr/bin/env python3
"""
Cline Hook: PreToolUse (Inject Context)
Injects file context and environment info before tool execution.
Copy to ~/.cline/hooks/PreToolUse.py and chmod +x
"""

import sys
import json
import os
import subprocess
from pathlib import Path

def get_git_branch() -> str | None:
    """Get current git branch."""
    try:
        result = subprocess.run(
            ["git", "branch", "--show-current"],
            capture_output=True,
            text=True,
            timeout=2
        )
        branch = result.stdout.strip()
        return branch if branch else None
    except Exception:
        return None

def get_node_version() -> str | None:
    """Get Node.js version."""
    try:
        result = subprocess.run(
            ["node", "--version"],
            capture_output=True,
            text=True,
            timeout=2
        )
        return result.stdout.strip() if result.returncode == 0 else None
    except Exception:
        return None

def get_file_context(file_path: str) -> str | None:
    """Get context about related files."""
    path = Path(file_path)

    # For TypeScript files, check for test files
    if path.suffix in [".ts", ".tsx"]:
        test_file = path.with_stem(path.stem).with_suffix(".test.ts")
        if test_file.exists():
            return f"Associated test file exists: {test_file}"

    # For package.json, mention lock files
    if path.name == "package.json":
        lock_files = []
        for lock in ["package-lock.json", "yarn.lock", "pnpm-lock.yaml"]:
            if (path.parent / lock).exists():
                lock_files.append(lock)

        if lock_files:
            return f"Related lock files: {', '.join(lock_files)}"

    # For config files, mention related configs
    if path.name.endswith(".config.ts") or path.name.endswith(".config.js"):
        basename = path.stem.replace(".config", "")
        parent = path.parent
        related = []
        for ext in [".ts", ".js", ".json"]:
            env_file = parent / f"{basename}.env{ext}"
            if env_file.exists():
                related.append(f"{env_file.name}")
        if related:
            return f"Related config files: {', '.join(related)}"

    return None

def main():
    try:
        event = json.load(sys.stdin)
    except json.JSONDecodeError as e:
        print(json.dumps({"errorMessage": f"Failed to parse: {e}"}))
        return

    tool_call = event.get("tool_call", {})
    tool_name = tool_call.get("name", "")
    tool_input = tool_call.get("input", {})

    # Inject file context when reading files
    if tool_name == "read_files":
        file_path = tool_input.get("filePath", "")
        if file_path:
            context = get_file_context(file_path)
            if context:
                print(json.dumps({"context": context}))
                return

    # Inject environment context for run_commands
    if tool_name == "run_commands":
        context_parts = []

        node_version = get_node_version()
        if node_version:
            context_parts.append(f"node {node_version}")

        git_branch = get_git_branch()
        if git_branch:
            context_parts.append(f"git branch: {git_branch}")

        if context_parts:
            context = "Environment: " + ", ".join(context_parts)
            print(json.dumps({"context": context}))
            return

    # Allow other tools without modification
    print(json.dumps({}))

if __name__ == "__main__":
    main()

#!/usr/bin/env bun
/**
 * Cline Hook: PreToolUse (Modify Input)
 * Demonstrates how to modify tool inputs before execution.
 * Useful for: normalizing paths, adding default options, sanitizing inputs.
 * Copy to ~/.cline/hooks/PreToolUse.ts and chmod +x
 */

interface ToolInput {
	[key: string]: unknown;
}

interface ToolCall {
	id: string;
	name: string;
	input: ToolInput;
}

interface HookEvent {
	hookName: string;
	tool_call: ToolCall;
	preToolUse: {
		toolName: string;
		parameters: Record<string, unknown>;
	};
}

interface HookControl {
	context?: string;
	overrideInput?: Record<string, unknown>;
}

function normalizeFilePath(path: string): string {
	// Convert backslashes to forward slashes (Windows paths)
	let normalized = path.replace(/\\/g, "/");

	// Resolve ~/ to home directory
	const home = process.env.HOME || process.env.USERPROFILE;
	if (normalized.startsWith("~/") && home) {
		normalized = normalized.replace(/^~/, home);
	}

	return normalized;
}

async function main(): Promise<void> {
	let event: HookEvent;

	try {
		const input = await Bun.stdin.text();
		event = JSON.parse(input) as HookEvent;
	} catch (error) {
		const message =
			error instanceof Error ? error.message : "Unknown parse error";
		console.log(
			JSON.stringify({ errorMessage: `Failed to parse: ${message}` }),
		);
		return;
	}

	const toolCall = event.tool_call;
	const toolName = toolCall.name;
	const toolInput = toolCall.input as Record<string, unknown>;

	// Modify read_files input: normalize paths
	if (toolName === "read_files" && typeof toolInput.filePath === "string") {
		const normalized = normalizeFilePath(toolInput.filePath);
		if (normalized !== toolInput.filePath) {
			const control: HookControl = {
				context: `Normalized file path from "${toolInput.filePath}" to "${normalized}"`,
				overrideInput: {
					...toolInput,
					filePath: normalized,
				},
			};
			console.log(JSON.stringify(control));
			return;
		}
	}

	// Modify editor input: add safety defaults
	if (toolName === "editor" && typeof toolInput.filePath === "string") {
		// For critical files, add a reminder
		const filePath = toolInput.filePath as string;
		if (
			filePath.includes("package.json") ||
			filePath.includes(".env") ||
			filePath.includes("tsconfig")
		) {
			const control: HookControl = {
				context:
					"WARNING: You are about to modify a critical configuration file. Verify changes carefully.",
			};
			console.log(JSON.stringify(control));
			return;
		}
	}

	// Modify run_commands input: add safety flags
	if (toolName === "run_commands" && typeof toolInput.command === "string") {
		const cmd = toolInput.command as string;

		// Add safety flags to npm/yarn installs
		if (cmd.includes("npm install") && !cmd.includes("--save")) {
			const newCmd = cmd.replace("npm install", "npm install --save-exact");
			const control: HookControl = {
				context: "Added --save-exact flag for reproducible installs",
				overrideInput: {
					...toolInput,
					command: newCmd,
				},
			};
			console.log(JSON.stringify(control));
			return;
		}
	}

	// No modifications needed
	console.log(JSON.stringify({}));
}

main().catch((error) => {
	console.error("Hook error:", error);
	process.exit(1);
});

/**
 * Custom Compaction Runtime Hook Example
 *
 * Demonstrates message compaction through a plugin runtime hook. The hook runs
 * in `beforeModel`, estimates request size, preserves the first user message
 * and recent working context, and replaces older middle history with one
 * summary message before the provider request.
 *
 * Installation:
 *   cline plugin install https://github.com/cline/cline/blob/main/sdk/examples/hooks/custom-compaction-hook.example.ts --cwd .
 *
 * Usage:
 *   cline -i "Search the codebase for dispatcher usage, then summarize it"
 *
 * Note: for most plugin-owned message rewrites, prefer registerMessageBuilder().
 * This example exists for cases where you specifically need runtime-hook access
 * to the current request and snapshot.
 */

import type { AgentPlugin } from "@cline/core";
import { estimateTokens as estimateTokensFromChars } from "@cline/shared";

type PluginHooks = NonNullable<AgentPlugin["hooks"]>;
type BeforeModelHook = NonNullable<PluginHooks["beforeModel"]>;
type BeforeModelContext = Parameters<BeforeModelHook>[0];
type AgentMessage = BeforeModelContext["request"]["messages"][number];
type AgentMessagePart = AgentMessage["content"][number];

const MAX_INPUT_TOKENS = 120_000;
const COMPACT_AT_RATIO = 0.75;
const PRESERVE_RECENT_TOKENS = 24_000;
const SUMMARY_PREVIEW_CHARS = 800;

function estimateTokens(text: string): number {
	return estimateTokensFromChars(text.length);
}

function preview(text: string, limit = SUMMARY_PREVIEW_CHARS): string {
	const trimmed = text.trim();
	if (trimmed.length <= limit) {
		return trimmed;
	}
	return `${trimmed.slice(0, limit).trim()}\n...[${trimmed.length - limit} more chars summarized]`;
}

function stringifyUnknown(value: unknown): string {
	if (typeof value === "string") {
		return value;
	}
	try {
		return JSON.stringify(value);
	} catch {
		return String(value);
	}
}

function serializePart(message: AgentMessage, part: AgentMessagePart): string {
	switch (part.type) {
		case "text":
			return `[${message.role}]: ${part.text}`;
		case "reasoning":
			return `[assistant reasoning]: ${preview(part.text, 300)}`;
		case "image":
			return `[${message.role} image]: ${part.mediaType ?? "unknown"}`;
		case "media":
			return `[assistant generated ${part.media.modality}]: ${part.media.mediaType}`;
		case "file":
			return `[${message.role} file ${part.path}]: ${preview(part.content, 500)}`;
		case "tool-call":
			return `[assistant tool call]: ${part.toolName}(${stringifyUnknown(part.input)})`;
		case "tool-result":
			return `[tool result ${part.toolName}]: ${preview(stringifyUnknown(part.output), 500)}`;
	}
}

function serializeMessage(message: AgentMessage): string {
	return message.content.map((part) => serializePart(message, part)).join("\n");
}

function estimateMessageTokens(message: AgentMessage): number {
	return estimateTokens(serializeMessage(message));
}

function isTurnStartMessage(message: AgentMessage): boolean {
	return (
		message.role === "user" &&
		message.content.some((part) => part.type === "text")
	);
}

function findFirstUserIndex(messages: readonly AgentMessage[]): number {
	return messages.findIndex(isTurnStartMessage);
}

function findRecentStartIndex(messages: readonly AgentMessage[]): number {
	let tokens = 0;
	for (let index = messages.length - 1; index >= 0; index -= 1) {
		const message = messages[index];
		if (!message) {
			continue;
		}
		tokens += estimateMessageTokens(message);
		if (tokens >= PRESERVE_RECENT_TOKENS) {
			return index;
		}
	}
	return 0;
}

function collectToolNames(messages: readonly AgentMessage[]): string[] {
	const names = new Set<string>();
	for (const message of messages) {
		for (const part of message.content) {
			if (part.type === "tool-call" || part.type === "tool-result") {
				names.add(part.toolName);
			}
		}
	}
	return [...names].sort((left, right) => left.localeCompare(right));
}

function collectTouchedFiles(messages: readonly AgentMessage[]): string[] {
	const paths = new Set<string>();
	for (const message of messages) {
		for (const part of message.content) {
			if (part.type === "file") {
				paths.add(part.path);
			}
			if (part.type === "tool-call") {
				for (const value of Object.values(
					typeof part.input === "object" && part.input !== null
						? part.input
						: {},
				)) {
					if (typeof value === "string" && value.includes("/")) {
						paths.add(value);
					}
				}
			}
		}
	}
	return [...paths].sort((left, right) => left.localeCompare(right));
}

function buildCompactionSummary(
	compacted: readonly AgentMessage[],
	tokensBefore: number,
): AgentMessage {
	const roleCounts = compacted.reduce<Record<string, number>>(
		(counts, message) => {
			counts[message.role] = (counts[message.role] ?? 0) + 1;
			return counts;
		},
		{},
	);
	const tools = collectToolNames(compacted);
	const files = collectTouchedFiles(compacted);
	const highlights = compacted
		.map(serializeMessage)
		.map((line) => preview(line, 500))
		.slice(-6);

	return {
		id: `hook_compaction_${Date.now()}`,
		role: "user",
		createdAt: Date.now(),
		metadata: {
			kind: "example_hook_compaction_summary",
			tokensBefore,
			messagesCompacted: compacted.length,
		},
		content: [
			{
				type: "text",
				text: `Context summary:

## Compacted Range
- Messages compacted: ${compacted.length}
- Estimated tokens before compaction: ${tokensBefore}
- Roles: ${Object.entries(roleCounts)
					.map(([role, count]) => `${role}=${count}`)
					.join(", ")}

## Tool Activity
${tools.length > 0 ? tools.map((tool) => `- ${tool}`).join("\n") : "- none"}

## Files Mentioned
${files.length > 0 ? files.map((path) => `- ${path}`).join("\n") : "- none"}

## Recent Highlights From Compacted History
${highlights.length > 0 ? highlights.map((item) => `- ${item}`).join("\n") : "- none"}

Continue from this summary plus the preserved recent messages below.`,
			},
		],
	};
}

const plugin: AgentPlugin = {
	name: "custom-compaction-before-model-hook",
	manifest: {
		capabilities: ["hooks"],
	},

	hooks: {
		beforeModel({ request }) {
			const messages = request.messages;
			const totalTokens = messages.reduce(
				(total, message) => total + estimateMessageTokens(message),
				0,
			);
			if (totalTokens < MAX_INPUT_TOKENS * COMPACT_AT_RATIO) {
				return undefined;
			}

			const firstUserIndex = findFirstUserIndex(messages);
			if (firstUserIndex < 0) {
				return undefined;
			}

			const recentStartIndex = Math.max(
				firstUserIndex + 1,
				findRecentStartIndex(messages),
			);
			if (recentStartIndex <= firstUserIndex + 1) {
				return undefined;
			}

			const prefix = messages.slice(0, firstUserIndex + 1);
			const compacted = messages.slice(firstUserIndex + 1, recentStartIndex);
			const recent = messages.slice(recentStartIndex);
			if (compacted.length === 0) {
				return undefined;
			}

			return {
				messages: [
					...prefix,
					buildCompactionSummary(compacted, totalTokens),
					...recent,
				],
			};
		},
	},
};

export { plugin };
export default plugin;

{
	"name": "examples",
	"description": "Example apps for the Cline SDK",
	"type": "module",
	"private": true,
	"scripts": {
		"typecheck": "tsc --noEmit",
		"clean": "rm -rf node_modules dist"
	},
	"devDependencies": {
		"@types/bun": "^1.3.10"
	},
	"peerDependencies": {
		"typescript": "^5"
	},
	"dependencies": {
		"@cline/core": "workspace:*"
	}
}

import {
	existsSync,
	mkdirSync,
	readdirSync,
	readFileSync,
	writeFileSync,
} from "node:fs";
import { dirname, isAbsolute, join, relative, resolve, sep } from "node:path";
import { fileURLToPath } from "node:url";
import {
	type AgentPlugin,
	type AgentTool,
	type AgentToolContext,
	ClineCore,
	createTool,
	type ITelemetryService,
	stripUtf8Bom,
} from "@cline/core";
import YAML from "yaml";
import { z } from "zod";

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

type SessionManager = ClineCore;

/** Minimal plugin host interface injected by the runtime via globalThis. */
interface ClinePluginHost {
	emitEvent?: (name: string, payload?: unknown) => void;
}

declare global {
	var __clinePluginHost: ClinePluginHost | undefined;
}

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

const MODULE_DIR = dirname(fileURLToPath(import.meta.url));
const BUNDLED_AGENTS_DIR = join(MODULE_DIR, "agents");
const BUNDLED_SKILLS_DIR = join(MODULE_DIR, "skills");

function resolveDefaultHomeDir(): string {
	const envHome = process?.env?.HOME?.trim();
	if (envHome && envHome !== "~") {
		return envHome;
	}
	const envUserProfile = process?.env?.USERPROFILE?.trim();
	if (envUserProfile) {
		return envUserProfile;
	}
	const envHomeDrive = process?.env?.HOMEDRIVE?.trim();
	const envHomePath = process?.env?.HOMEPATH?.trim();
	if (envHomeDrive && envHomePath) {
		return `${envHomeDrive}${envHomePath}`;
	}
	return "~";
}

function resolveClineDirPath(): string {
	const explicitDir = process.env.CLINE_DIR?.trim();
	if (explicitDir) {
		return explicitDir;
	}
	return join(resolveDefaultHomeDir(), ".cline");
}

function resolveClineDataDirPath(): string {
	const explicitDir = process.env.CLINE_DATA_DIR?.trim();
	if (explicitDir) {
		return explicitDir;
	}
	return join(resolveClineDirPath(), "data");
}

function resolveGlobalAgentsDirPath(): string {
	return join(resolveClineDataDirPath(), "settings", "agents");
}

const HANDOFFS_DIR = join(
	resolveClineDataDirPath(),
	"plugins",
	"subagents",
	"handoffs",
);
const GLOBAL_SKILLS_DIR = join(resolveClineDataDirPath(), "settings", "skills");

// Agent and skill definitions live in the `agents/` and `skills/`
// directories alongside this file. They are loaded at runtime from disk.

/** Safe identifier pattern for conversation IDs used in filesystem paths. */
const SAFE_ID_RE = /^[A-Za-z0-9_-]+$/;
const HANDOFF_PATH_ALLOWED_RE = /^[A-Za-z0-9._/-]+$/;
const HANDOFF_PATH_MAX_LENGTH = 240;

const envOr = (key: string, fallback: string): string =>
	process.env[key]?.trim() || fallback;

const DEFAULT_PROVIDER_ID = envOr("CLINE_SUBAGENT_PROVIDER_ID", "cline");
const DEFAULT_MODEL_ID = envOr(
	"CLINE_SUBAGENT_MODEL_ID",
	"anthropic/claude-sonnet-4.6",
);
type SubagentBackendMode = "auto" | "hub" | "local";

const DEFAULT_BACKEND_MODE = envOr("CLINE_SUBAGENTS_BACKEND_MODE", "auto");
const DEFAULT_AGENT_PRESET = envOr("CLINE_SUBAGENT_DEFAULT_PRESET", "phantom");

// ---------------------------------------------------------------------------
// Agent & Skill Definitions
// ---------------------------------------------------------------------------

interface AgentDefinition {
	name: string;
	description?: string;
	providerId?: string;
	modelId?: string;
	systemPrompt: string;
	cwd?: string;
	maxIterations?: number;
	source: "bundled" | "global" | "project";
}

interface SkillDefinition {
	name: string;
	description?: string;
	content: string;
	source: "bundled" | "global" | "project";
}

interface RunningSubagent {
	sessionId: string;
	parentSessionId?: string;
	name: string;
	task: string;
	agent?: string;
	startedAt: number;
	status: "running" | "completed" | "failed";
	resultText?: string;
	error?: string;
	finishReason?: string;
	completedAt?: number;
}

// ---------------------------------------------------------------------------
// State
// ---------------------------------------------------------------------------

const subagents = new Map<string, RunningSubagent>();
let sessionManagerPromise: Promise<SessionManager> | undefined;

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/**
 * Cast a fully-typed tool to the `AgentTool<unknown, unknown>` expected by
 * the plugin API's `registerTool` method. This is safe at runtime because the
 * registry only invokes `execute` with validated input that matches the
 * tool's `inputSchema`.
 */
function toRegisteredTool<I, O>(
	tool: AgentTool<I, O>,
): AgentTool<unknown, unknown> {
	return tool as AgentTool<unknown, unknown>;
}

function optStr(v: unknown): string | undefined {
	return typeof v === "string" && v.trim() ? v.trim() : undefined;
}

function optInt(v: unknown): number | undefined {
	return typeof v === "number" && Number.isFinite(v) && v > 0
		? Math.floor(v)
		: undefined;
}

function parseFrontmatter(md: string): {
	data: Record<string, unknown>;
	body: string;
} {
	// stripUtf8Bom keeps the frontmatter match below working for files saved with a leading
	// UTF-8 BOM (see cline/cline#12151).
	md = stripUtf8Bom(md);
	const m = md.match(/^---\r?\n([\s\S]*?)\r?\n---\r?\n?([\s\S]*)$/);
	if (!m) return { data: {}, body: md.trim() };
	try {
		const frontmatter = m[1] ?? "";
		const body = m[2] ?? "";
		const parsed = YAML.parse(frontmatter);
		return {
			data:
				parsed && typeof parsed === "object" && !Array.isArray(parsed)
					? (parsed as Record<string, unknown>)
					: {},
			body: body.trim(),
		};
	} catch {
		// Malformed YAML frontmatter — treat as plain markdown with no metadata.
		return { data: {}, body: md.trim() };
	}
}

function readMarkdownDir(
	dirPath: string,
	source: AgentDefinition["source"],
): Array<{
	name: string;
	data: Record<string, unknown>;
	body: string;
	source: typeof source;
}> {
	if (!existsSync(dirPath)) return [];
	const results: Array<{
		name: string;
		data: Record<string, unknown>;
		body: string;
		source: typeof source;
	}> = [];
	for (const entry of readdirSync(dirPath, { withFileTypes: true })) {
		if (!entry.isFile() || !entry.name.endsWith(".md")) continue;
		try {
			const { data, body } = parseFrontmatter(
				readFileSync(join(dirPath, entry.name), "utf8"),
			);
			if (!body) continue;
			const name = optStr(data.name) ?? entry.name.replace(/\.md$/, "");
			results.push({ name, data, body, source });
		} catch {}
	}
	return results;
}

function readAgentDefinitions(baseCwd: string): AgentDefinition[] {
	const dirs: Array<{ path: string; source: AgentDefinition["source"] }> = [
		{ path: BUNDLED_AGENTS_DIR, source: "bundled" },
		{ path: resolveGlobalAgentsDirPath(), source: "global" },
		{ path: join(baseCwd, ".cline", "agents"), source: "project" },
	];
	const defs = new Map<string, AgentDefinition>();
	for (const { path, source } of dirs) {
		for (const entry of readMarkdownDir(path, source)) {
			defs.set(entry.name, {
				name: entry.name,
				description: optStr(entry.data.description),
				providerId: optStr(entry.data.providerId),
				modelId: optStr(entry.data.modelId),
				systemPrompt: entry.body,
				cwd: optStr(entry.data.cwd),
				maxIterations: optInt(entry.data.maxIterations),
				source: entry.source,
			});
		}
	}
	return [...defs.values()].sort((a, b) => a.name.localeCompare(b.name));
}

function readSkillDefinitions(baseCwd: string): SkillDefinition[] {
	const dirs: Array<{ path: string; source: SkillDefinition["source"] }> = [
		{ path: BUNDLED_SKILLS_DIR, source: "bundled" },
		{ path: GLOBAL_SKILLS_DIR, source: "global" },
		{ path: join(baseCwd, ".cline", "skills"), source: "project" },
	];
	const defs = new Map<string, SkillDefinition>();
	for (const { path, source } of dirs) {
		for (const entry of readMarkdownDir(path, source)) {
			defs.set(entry.name, {
				name: entry.name,
				description: optStr(entry.data.description),
				content: entry.body,
				source: entry.source,
			});
		}
	}
	return [...defs.values()].sort((a, b) => a.name.localeCompare(b.name));
}

function parentSessionId(ctx: AgentToolContext): string | undefined {
	const id = ctx.metadata?.sessionId;
	return typeof id === "string" && id.trim() ? id.trim() : undefined;
}

function sanitizeConversationId(conversationId: string): string {
	const trimmed = conversationId.trim();
	if (!trimmed || !SAFE_ID_RE.test(trimmed)) {
		throw new Error(`Invalid conversation ID for filesystem use: "${trimmed}"`);
	}
	return trimmed;
}

function handoffsDir(ctx: AgentToolContext): string {
	const conversationId = ctx.conversationId ?? parentSessionId(ctx);
	if (!conversationId) {
		throw new Error("Missing conversation ID for handoff storage");
	}
	const safeId = sanitizeConversationId(conversationId);
	const dir = join(HANDOFFS_DIR, safeId);
	mkdirSync(dir, { recursive: true });
	return dir;
}

function resolveHandoffPath(
	ctx: AgentToolContext,
	relativePath: string,
): string {
	const handoffPath = validateHandoffRelativePath(relativePath);
	const dir = handoffsDir(ctx);
	const resolved = resolve(dir, handoffPath);
	const pathFromHandoffsDir = relative(dir, resolved);
	if (
		!pathFromHandoffsDir ||
		pathFromHandoffsDir === ".." ||
		pathFromHandoffsDir.startsWith(`..${sep}`) ||
		isAbsolute(pathFromHandoffsDir)
	) {
		throw new Error(`Handoff path escapes directory: ${relativePath}`);
	}
	return resolved;
}

function validateHandoffRelativePath(relativePath: string): string {
	const trimmed = relativePath.trim();
	if (!trimmed) {
		throw new Error("Handoff path must not be empty");
	}
	if (trimmed.length > HANDOFF_PATH_MAX_LENGTH) {
		throw new Error(
			`Handoff path must be ${HANDOFF_PATH_MAX_LENGTH} characters or fewer`,
		);
	}
	if (trimmed.startsWith("/")) {
		throw new Error(`Handoff path must be relative: ${relativePath}`);
	}
	if (!HANDOFF_PATH_ALLOWED_RE.test(trimmed)) {
		throw new Error(
			"Use a relative file path with letters, numbers, '.', '_', '-', or '/'.",
		);
	}
	if (trimmed.split("/").includes("..")) {
		throw new Error(`Handoff path must not contain '..': ${relativePath}`);
	}
	return trimmed;
}

function emitSteer(sessionId: string | undefined, prompt: string): void {
	if (sessionId && prompt.trim()) {
		globalThis.__clinePluginHost?.emitEvent?.("steer_message", {
			sessionId,
			prompt,
		});
	}
}

async function getSessionManager(): Promise<SessionManager> {
	sessionManagerPromise ??= ClineCore.create({
		backendMode: resolveSubagentBackendMode(DEFAULT_BACKEND_MODE),
	}).catch((err) => {
		// Clear the cached promise so subsequent calls can retry.
		sessionManagerPromise = undefined;
		throw err;
	});
	return sessionManagerPromise;
}

function resolveSubagentBackendMode(value: string): SubagentBackendMode {
	switch (value) {
		case "auto":
		case "hub":
		case "local":
			return value;
		default:
			return "auto";
	}
}

function extractLastAssistantText(
	messages: Array<{ role?: string; content?: unknown }>,
): string {
	for (let i = messages.length - 1; i >= 0; i--) {
		const msg = messages[i];
		if (msg?.role !== "assistant" || !Array.isArray(msg.content)) continue;
		const text = (msg.content as Array<{ type?: string; text?: unknown }>)
			.filter((b) => b?.type === "text" && typeof b.text === "string")
			.map((b) => b.text as string)
			.join("")
			.trim();
		if (text) return text;
	}
	return "";
}

function elapsed(start: number, end = Date.now()): string {
	const s = Math.max(0, Math.floor((end - start) / 1000));
	return s < 60 ? `${s}s` : `${Math.floor(s / 60)}m ${s % 60}s`;
}

function steerPrompt(subagent: RunningSubagent): string {
	const time = elapsed(subagent.startedAt, subagent.completedAt ?? Date.now());
	const header =
		subagent.status === "completed"
			? `Sub-agent "${subagent.name}" completed (${time}).`
			: `Sub-agent "${subagent.name}" failed (${time}).`;
	const body = subagent.resultText?.trim() || subagent.error?.trim() || "";
	return [header, body, `Session ID: ${subagent.sessionId}`]
		.filter(Boolean)
		.join("\n\n");
}

/**
 * Host telemetry captured in setup(). Module-level so background work like
 * runSubagentTurn can report outcomes. Always optional: feature-detect with
 * `?.` — it is undefined when the host has no telemetry service. Only pass
 * plain JSON data as properties; in sandboxed plugins the calls are bridged
 * to the host over IPC, which namespaces them under `plugin.` and stamps
 * `plugin_name`.
 */
let pluginTelemetry: ITelemetryService | undefined;

async function runSubagentTurn(
	subagent: RunningSubagent,
	message: string,
	steer: boolean,
): Promise<void> {
	try {
		const mgr = await getSessionManager();
		const result = await mgr.send({
			sessionId: subagent.sessionId,
			prompt: message,
		});
		const messages = await mgr.readMessages(subagent.sessionId);
		subagent.status = "completed";
		subagent.finishReason = result?.finishReason;
		subagent.resultText =
			result?.text?.trim() || extractLastAssistantText(messages) || "";
		subagent.error = undefined;
		subagent.completedAt = Date.now();
	} catch (err) {
		subagent.status = "failed";
		subagent.error = err instanceof Error ? err.message : String(err);
		subagent.completedAt = Date.now();
	}
	// Outcome telemetry: status as an event, wall-clock as a histogram. Keep
	// properties low-cardinality (status, preset) — never task text or output.
	pluginTelemetry?.capture({
		event: "subagent_turn_completed",
		properties: {
			status: subagent.status,
			preset: subagent.agent,
			finish_reason: subagent.finishReason,
		},
	});
	pluginTelemetry?.recordHistogram(
		"subagents.turn_duration_ms",
		(subagent.completedAt ?? Date.now()) - subagent.startedAt,
		{ status: subagent.status },
	);
	if (steer) emitSteer(subagent.parentSessionId, steerPrompt(subagent));
}

