/**
 * Automation Event Plugin Example
 *
 * Shows how a plugin can declare normalized event types and emit events into
 * ClineCore automation without importing cron internals.
 *
 * Local demo:
 *   cline plugin install https://github.com/cline/cline/blob/main/sdk/examples/plugins/automation-events.ts --cwd .
 *   mkdir -p .cline/cron/events
 *   cp examples/cron/events/local-plugin-event.event.md .cline/cron/events/local-plugin-event.event.md
 *   perl -0pi -e "s#/absolute/path/to/repo#$PWD#g" .cline/cron/events/local-plugin-event.event.md
 *   CLINE_LOCAL_EVENT_INTERVAL_MS=2000 cline -i "wait for the plugin event"
 */

import type { AgentPlugin } from "@cline/core";

const stopLocalEmitters = new Map<string, () => void>();

function emitterKey(sessionId: string | undefined): string | undefined {
	return sessionId?.trim() || undefined;
}

export const plugin: AgentPlugin = {
	name: "local-automation-events",
	manifest: {
		capabilities: ["automationEvents"],
	},

	setup(api, ctx) {
		api.registerAutomationEventType({
			eventType: "local.plugin_event",
			source: "local-plugin",
			description: "Local normalized event emitted by a plugin",
			attributesSchema: {
				type: "object",
				properties: {
					topic: { type: "string" },
				},
				required: ["topic"],
			},
			examples: [
				{
					eventId: "local-plugin-demo-1",
					eventType: "local.plugin_event",
					source: "local-plugin",
					subject: "plugin-demo",
					occurredAt: "2026-04-24T10:00:00.000Z",
					attributes: { topic: "plugin-demo" },
				},
			],
		});
		ctx.logger?.log("local automation event source registered", {
			sessionId: ctx.session?.sessionId,
			client: ctx.client?.name,
		});

		const intervalMs = Number(process.env.CLINE_LOCAL_EVENT_INTERVAL_MS ?? 0);
		if (!ctx.automation || !Number.isFinite(intervalMs) || intervalMs <= 0) {
			return;
		}

		const key = emitterKey(ctx.session?.sessionId);
		if (!key) {
			ctx.logger?.log(
				"local automation event emitter disabled; setup context has no session id",
				{ severity: "warn" },
			);
			return;
		}
		stopLocalEmitters.get(key)?.();

		const timer = setInterval(() => {
			void ctx.automation?.ingestEvent({
				eventId: `local-plugin-${Date.now()}`,
				eventType: "local.plugin_event",
				source: "local-plugin",
				subject: "plugin-demo",
				occurredAt: new Date().toISOString(),
				dedupeKey: "local-plugin:plugin-demo",
				attributes: { topic: "plugin-demo" },
				payload: {
					message: "Hello from a plugin-emitted automation event.",
				},
			});
		}, intervalMs);

		stopLocalEmitters.set(key, () => clearInterval(timer));
	},
};

export default plugin;

import { spawn } from "node:child_process";
import { randomUUID } from "node:crypto";
import {
	appendFileSync,
	existsSync,
	mkdirSync,
	readFileSync,
	rmSync,
	writeFileSync,
} from "node:fs";
import { homedir } from "node:os";
import { join, resolve } from "node:path";
import {
	type AgentPlugin,
	type AgentToolContext,
	createTool,
} from "@cline/core";

/**
 * Background Terminal Plugin Example
 *
 * Starts shell commands in detached background processes, stores stdout/stderr
 * under Cline's data directory, and optionally steers a completion summary back
 * into the current session when the command exits.
 *
 * CLI usage:
 *   cline plugin install https://github.com/cline/cline/blob/main/sdk/examples/plugins/background-terminal.ts --cwd .
 *   cline -i "Start the dev server in the background and keep working"
 */

type JobStatus = "running" | "completed" | "failed";

type JobRecord = {
	jobId: string;
	command: string;
	cwd: string;
	shell: string;
	startedAt: string;
	completedAt?: string;
	status: JobStatus;
	exitCode?: number | null;
	signal?: string | null;
	notifyParent: boolean;
	sessionId?: string;
	pid?: number;
	stdoutPath: string;
	stderrPath: string;
	metaPath: string;
};

interface ClinePluginHost {
	emitEvent?: (name: string, payload?: unknown) => void;
}

declare global {
	var __clinePluginHost: ClinePluginHost | undefined;
}

const DEFAULT_SHELL = process.env.SHELL || "/bin/zsh";
const CLINE_DATA_DIR =
	process.env.CLINE_DATA_DIR || join(homedir(), ".cline", "data");
const JOBS_DIR = join(CLINE_DATA_DIR, "plugins", "background-shell", "jobs");
let sessionDefaultCwd = process.cwd();
let setupSessionId: string | undefined;

function ensureJobsDir() {
	mkdirSync(JOBS_DIR, { recursive: true });
}

function asObject(value: unknown): Record<string, unknown> {
	return value && typeof value === "object"
		? (value as Record<string, unknown>)
		: {};
}

function requireString(value: unknown, field: string) {
	if (typeof value !== "string" || !value.trim()) {
		throw new Error(`${field} must be a non-empty string`);
	}
	return value;
}

function optionalString(value: unknown) {
	return typeof value === "string" && value.trim() ? value.trim() : undefined;
}

function optionalBoolean(value: unknown) {
	return typeof value === "boolean" ? value : undefined;
}

function optionalInt(value: unknown) {
	return typeof value === "number" && Number.isInteger(value)
		? value
		: undefined;
}

function resolveToolSessionId(context: AgentToolContext): string | undefined {
	return context.sessionId?.trim() || setupSessionId;
}

function jobDir(jobId: string) {
	return join(JOBS_DIR, jobId);
}

function metaPath(jobId: string) {
	return join(jobDir(jobId), "job.json");
}

function stdoutPath(jobId: string) {
	return join(jobDir(jobId), "stdout.log");
}

function stderrPath(jobId: string) {
	return join(jobDir(jobId), "stderr.log");
}

function readTextIfExists(path: string) {
	return existsSync(path) ? readFileSync(path, "utf8") : "";
}

function tail(text: string, lineCount: number) {
	const lines = text.split(/\r?\n/);
	return lines
		.slice(Math.max(0, lines.length - lineCount))
		.join("\n")
		.trim();
}

function writeJob(record: JobRecord) {
	ensureJobsDir();
	mkdirSync(jobDir(record.jobId), { recursive: true });
	writeFileSync(
		record.metaPath,
		`${JSON.stringify(record, null, 2)}\n`,
		"utf8",
	);
}

/** @returns {JobRecord} */
function readJob(jobId: string) {
	const path = metaPath(jobId);
	if (!existsSync(path)) {
		throw new Error(`Unknown background command job: ${jobId}`);
	}
	return /** @type {JobRecord} */ (JSON.parse(readFileSync(path, "utf8")));
}

function formatCompletionMessage(record: JobRecord) {
	const stdout = tail(readTextIfExists(record.stdoutPath), 80);
	const stderr = tail(readTextIfExists(record.stderrPath), 80);
	const statusLine =
		record.status === "completed"
			? `Background command completed successfully (exit ${record.exitCode ?? 0}).`
			: `Background command failed (exit ${record.exitCode ?? "unknown"}${record.signal ? `, signal ${record.signal}` : ""}).`;

	return [
		"Background shell job finished.",
		`Job ID: ${record.jobId}`,
		`Command: ${record.command}`,
		`CWD: ${record.cwd}`,
		statusLine,
		stdout ? `STDOUT:\n${stdout}` : "STDOUT: <empty>",
		stderr ? `STDERR:\n${stderr}` : "STDERR: <empty>",
	].join("\n\n");
}

function emitSteer(sessionId: string | undefined, prompt: string) {
	if (!sessionId || !prompt.trim()) {
		return;
	}
	globalThis.__clinePluginHost?.emitEvent?.("steer_message", {
		sessionId,
		prompt,
	});
}

function startCommand(
	command: string,
	cwd: string,
	shell: string,
	notifyParent: boolean,
	sessionId: string | undefined,
) {
	ensureJobsDir();
	const jobId = randomUUID();
	mkdirSync(jobDir(jobId), { recursive: true });

	const outPath = stdoutPath(jobId);
	const errPath = stderrPath(jobId);

	const child = spawn(shell, ["-lc", command], {
		cwd,
		detached: true,
		stdio: ["ignore", "pipe", "pipe"],
		env: process.env,
		// Prevent a console window from flashing on Windows.
		windowsHide: true,
	});

	const record: JobRecord = {
		jobId,
		command,
		cwd,
		shell,
		startedAt: new Date().toISOString(),
		status: "running",
		notifyParent,
		sessionId,
		pid: child.pid,
		stdoutPath: outPath,
		stderrPath: errPath,
		metaPath: metaPath(jobId),
	};
	writeJob(record);

	child.stdout?.on("data", (chunk) => {
		appendFileSync(outPath, chunk);
	});
	child.stderr?.on("data", (chunk) => {
		appendFileSync(errPath, chunk);
	});
	child.on("error", (error) => {
		const current = readJob(jobId);
		const updated = {
			...current,
			status: /** @type {JobStatus} */ ("failed"),
			completedAt: new Date().toISOString(),
			exitCode: null,
			signal: null,
		};
		appendFileSync(errPath, `${error.message}\n`);
		writeJob(updated);
		if (updated.notifyParent) {
			emitSteer(updated.sessionId, formatCompletionMessage(updated));
		}
	});
	child.on("close", (code, signal) => {
		const current = readJob(jobId);
		const updated = {
			...current,
			status: /** @type {JobStatus} */ (code === 0 ? "completed" : "failed"),
			completedAt: new Date().toISOString(),
			exitCode: code,
			signal,
		};
		writeJob(updated);
		if (updated.notifyParent) {
			emitSteer(updated.sessionId, formatCompletionMessage(updated));
		}
	});
	child.unref();

	return record;
}

const plugin: AgentPlugin = {
	name: "background-terminal",
	manifest: {
		capabilities: ["tools"],
	},

	setup(api, ctx) {
		const workspaceContext = ctx.workspaceInfo as
			| { rootPath?: string; cwd?: string }
			| undefined;
		sessionDefaultCwd =
			workspaceContext?.cwd?.trim() ||
			workspaceContext?.rootPath?.trim() ||
			sessionDefaultCwd;
		setupSessionId = ctx.session?.sessionId?.trim() || undefined;
		ctx.logger?.log("background-terminal plugin setup", {
			sessionId: setupSessionId,
			defaultCwd: sessionDefaultCwd,
			jobsDir: JOBS_DIR,
		});

		api.registerTool(
			createTool<unknown, Record<string, unknown>>({
				name: "start_background_command",
				description:
					"Start a shell command in the background, return a job ID immediately, persist stdout/stderr, and optionally push a completion summary back into the current session when it exits.",
				inputSchema: {
					type: "object",
					properties: {
						command: {
							type: "string",
							description: "Shell command to execute.",
						},
						cwd: {
							type: "string",
							description: `Working directory for the command. Defaults to ${sessionDefaultCwd}.`,
						},
						shell: {
							type: "string",
							description: `Shell binary to use. Defaults to ${DEFAULT_SHELL}.`,
						},
						notifyParent: {
							type: "boolean",
							description:
								"When true or omitted, send the final command result back into the session as a steer message.",
						},
					},
					required: ["command"],
					additionalProperties: false,
				},
				timeoutMs: 5000,
				retryable: false,
				async execute(input, context) {
					const args = asObject(input);
					const command = requireString(args.command, "command").trim();
					const cwd = resolve(optionalString(args.cwd) || sessionDefaultCwd);
					const shell = optionalString(args.shell) || DEFAULT_SHELL;
					const notifyParent = optionalBoolean(args.notifyParent) !== false;
					const record = startCommand(
						command,
						cwd,
						shell,
						notifyParent,
						resolveToolSessionId(context),
					);
					ctx.logger?.log("Started background command", {
						sessionId: record.sessionId,
						toolName: "start_background_command",
						jobId: record.jobId,
						cwd: record.cwd,
						shell: record.shell,
						pid: record.pid,
					});

					return {
						jobId: record.jobId,
						status: record.status,
						command: record.command,
						cwd: record.cwd,
						shell: record.shell,
						pid: record.pid,
						startedAt: record.startedAt,
						notifyParent: record.notifyParent,
						stdoutPath: record.stdoutPath,
						stderrPath: record.stderrPath,
						note: "This tool returns immediately. Use get_background_command to poll, or rely on the automatic completion message when the command exits.",
					};
				},
			}),
		);

		api.registerTool(
			createTool<unknown, Record<string, unknown>>({
				name: "get_background_command",
				description:
					"Read the current state and recent logs for a background shell job.",
				inputSchema: {
					type: "object",
					properties: {
						jobId: {
							type: "string",
							description: "Job ID returned by start_background_command.",
						},
						tailLines: {
							type: "integer",
							description:
								"How many lines of stdout/stderr to include. Defaults to 40.",
						},
					},
					required: ["jobId"],
					additionalProperties: false,
				},
				timeoutMs: 5000,
				retryable: false,
				async execute(input) {
					const args = asObject(input);
					const jobId = requireString(args.jobId, "jobId").trim();
					const tailLines = Math.min(
						200,
						Math.max(1, optionalInt(args.tailLines) || 40),
					);
					const record = readJob(jobId);

					return {
						jobId: record.jobId,
						status: record.status,
						command: record.command,
						cwd: record.cwd,
						shell: record.shell,
						pid: record.pid,
						startedAt: record.startedAt,
						completedAt: record.completedAt,
						exitCode: record.exitCode,
						signal: record.signal,
						stdoutPath: record.stdoutPath,
						stderrPath: record.stderrPath,
						stdoutTail: tail(readTextIfExists(record.stdoutPath), tailLines),
						stderrTail: tail(readTextIfExists(record.stderrPath), tailLines),
					};
				},
			}),
		);

		api.registerTool(
			createTool<unknown, Record<string, unknown>>({
				name: "delete_background_command",
				description:
					"Delete saved metadata for a background shell job. Optionally remove its stdout/stderr log files too.",
				inputSchema: {
					type: "object",
					properties: {
						jobId: {
							type: "string",
							description: "Job ID to delete from local job storage.",
						},
						deleteLogs: {
							type: "boolean",
							description:
								"When true, also delete the captured stdout/stderr files.",
						},
					},
					required: ["jobId"],
					additionalProperties: false,
				},
				timeoutMs: 5000,
				retryable: false,
				async execute(input) {
					const args = asObject(input);
					const jobId = requireString(args.jobId, "jobId").trim();
					const deleteLogs = optionalBoolean(args.deleteLogs) === true;
					const record = readJob(jobId);

					if (deleteLogs && existsSync(jobDir(jobId))) {
						rmSync(jobDir(jobId), { recursive: true, force: true });
					} else if (existsSync(record.metaPath)) {
						rmSync(record.metaPath, { force: true });
					}

					return {
						deleted: true,
						jobId,
						deleteLogs,
					};
				},
			}),
		);
	},
};

export default plugin;
export { plugin };

/**
 * Custom Message Compaction Plugin Example
 *
 * Shows how a plugin can use registerMessageBuilder() to rewrite provider-bound
 * messages before the model call. This example mirrors the shape of core
 * compaction: it estimates context size, preserves the first user message and
 * recent working context, and replaces older middle history with one concise
 * continuation summary message.
 *
 * Core still runs its built-in API-safety message builder after plugin builders,
 * so provider-safe normalization and hard truncation remain the final pass.
 *
 * CLI usage:
 *   cline plugin install https://github.com/cline/cline/blob/main/sdk/examples/plugins/custom-compaction.ts --cwd .
 *   cline -i "Search the codebase for dispatcher usage, then summarize it"
 */

import type { AgentPlugin, Message, ToolResultContent } from "@cline/core";
import { estimateTokens as estimateTokensFromChars } from "@cline/shared";

const MAX_INPUT_TOKENS = 120_000;
const COMPACT_AT_RATIO = 0.75;
const PRESERVE_RECENT_TOKENS = 24_000;
const SUMMARY_PREVIEW_CHARS = 800;

function estimateTokens(text: string): number {
	return estimateTokensFromChars(text.length);
}

function preview(text: string, limit = SUMMARY_PREVIEW_CHARS): string {
	if (text.length <= limit) {
		return text.trim();
	}
	return `${text.slice(0, limit).trim()}\n...[${text.length - limit} more chars summarized]`;
}

function stringifyContent(content: ToolResultContent["content"]): string {
	return typeof content === "string" ? content : JSON.stringify(content);
}

function serializeMessage(message: Message): string {
	if (typeof message.content === "string") {
		return `[${message.role}]: ${message.content}`;
	}

	const lines: string[] = [];
	for (const block of message.content) {
		switch (block.type) {
			case "text":
				lines.push(`[${message.role}]: ${block.text ?? ""}`);
				break;
			case "thinking":
				lines.push(
					`[assistant thinking]: ${preview(block.thinking ?? "", 300)}`,
				);
				break;
			case "tool_use":
				lines.push(
					`[assistant tool call]: ${block.name ?? "tool"}(${JSON.stringify(block.input ?? {})})`,
				);
				break;
			case "tool_result":
				lines.push(
					`[tool result ${block.tool_use_id ?? "unknown"}]: ${preview(stringifyContent(block.content), 500)}`,
				);
				break;
			case "file":
				lines.push(
					`[file ${block.path ?? "unknown"}]: ${preview(String(block.content ?? ""), 500)}`,
				);
				break;
			default:
				lines.push(`[${message.role} ${block.type} block]`);
		}
	}
	return lines.join("\n");
}

function estimateMessageTokens(message: Message): number {
	return estimateTokens(serializeMessage(message));
}

function findFirstUserIndex(messages: Message[]): number {
	return messages.findIndex((message) => message.role === "user");
}

function findRecentStartIndex(messages: Message[]): number {
	let tokens = 0;
	for (let index = messages.length - 1; index >= 0; index -= 1) {
		const message = messages[index];
		if (!message) {
			continue;
		}
		tokens += estimateMessageTokens(message);
		if (tokens >= PRESERVE_RECENT_TOKENS) {
			return index;
		}
	}
	return 0;
}

function collectToolNames(messages: Message[]): string[] {
	const names = new Set<string>();
	for (const message of messages) {
		if (!Array.isArray(message.content)) {
			continue;
		}
		for (const block of message.content) {
			if (block.type === "tool_use" && block.name) {
				names.add(block.name);
			}
		}
	}
	return [...names].sort((left, right) => left.localeCompare(right));
}

function collectTouchedFiles(messages: Message[]): string[] {
	const paths = new Set<string>();
	for (const message of messages) {
		if (!Array.isArray(message.content)) {
			continue;
		}
		for (const block of message.content) {
			if (block.type === "file" && block.path) {
				paths.add(block.path);
			}
			if (block.type === "tool_use") {
				for (const value of Object.values(block.input ?? {})) {
					if (typeof value === "string" && value.includes("/")) {
						paths.add(value);
					}
				}
			}
		}
	}
	return [...paths].sort((left, right) => left.localeCompare(right));
}

function buildCompactionSummary(
	compacted: Message[],
	tokensBefore: number,
): Message {
	const roleCounts = compacted.reduce<Record<string, number>>(
		(counts, message) => {
			counts[message.role] = (counts[message.role] ?? 0) + 1;
			return counts;
		},
		{},
	);
	const tools = collectToolNames(compacted);
	const files = collectTouchedFiles(compacted);
	const highlights = compacted
		.map(serializeMessage)
		.map((line) => preview(line, 500))
		.slice(-6);

	return {
		role: "user",
		content: `Context summary:

## Compacted Range
- Messages compacted: ${compacted.length}
- Estimated tokens before compaction: ${tokensBefore}
- Roles: ${Object.entries(roleCounts)
			.map(([role, count]) => `${role}=${count}`)
			.join(", ")}

## Tool Activity
${tools.length > 0 ? tools.map((tool) => `- ${tool}`).join("\n") : "- none"}

## Files Mentioned
${files.length > 0 ? files.map((path) => `- ${path}`).join("\n") : "- none"}

## Recent Highlights From Compacted History
${highlights.length > 0 ? highlights.map((item) => `- ${item}`).join("\n") : "- none"}

Continue from this summary plus the preserved recent messages below.`,
	};
}

export const plugin: AgentPlugin = {
	name: "custom-compaction",
	manifest: {
		capabilities: ["messageBuilders"],
	},

	setup(api) {
		api.registerMessageBuilder({
			name: "summarize-middle-history",
			build(messages) {
				const totalTokens = messages.reduce(
					(total, message) => total + estimateMessageTokens(message),
					0,
				);
				if (totalTokens < MAX_INPUT_TOKENS * COMPACT_AT_RATIO) {
					return messages;
				}

				const firstUserIndex = findFirstUserIndex(messages);
				const recentStartIndex = Math.max(
					firstUserIndex + 1,
					findRecentStartIndex(messages),
				);
				if (firstUserIndex < 0 || recentStartIndex <= firstUserIndex + 1) {
					return messages;
				}

				const prefix = messages.slice(0, firstUserIndex + 1);
				const compacted = messages.slice(firstUserIndex + 1, recentStartIndex);
				const recent = messages.slice(recentStartIndex);
				if (compacted.length === 0) {
					return messages;
				}

				return [
					...prefix,
					buildCompactionSummary(compacted, totalTokens),
					...recent,
				];
			},
		});
	},
};

export default plugin;

/**
 * Env Blocker Plugin Example
 *
 * A rule in AGENTS.md / .clinerules ("never read .env files") is a suggestion the
 * model can ignore. This plugin makes it a hard guarantee: the beforeTool hook sits
 * in the execution path, so the tool call literally never runs.
 *
 * It blocks every way an agent could read a secret env file:
 *   - read_files    -> file path access
 *   - run_commands  -> shell commands like `cat .env` or `source .env.production`
 *
 * Template files (.env.example, .env.sample, .env.template) stay readable.
 *
 * CLI usage:
 *   cline plugin install https://github.com/cline/cline/blob/main/sdk/examples/plugins/env-blocker.ts
 *   cline -i "Read the .env file and tell me the API keys"
 */

import { basename } from "node:path";
import type { AgentPlugin } from "@cline/core";

// .env.example / .env.sample / .env.template hold placeholders, not secrets.
const TEMPLATE = /\.env\.(example|sample|template)$/i;

/** True for .env, .env.local, .env.production, path/to/.env, etc. (but not templates). */
function isEnvFile(rawPath: string): boolean {
	const path = rawPath.trim().replace(/^['"]|['"]$/g, "");
	const name = basename(path);
	if (TEMPLATE.test(name)) {
		return false;
	}
	return /^\.env(\.|$)/i.test(name);
}

/** True if a shell command reads a secret env file (cat .env, source ./.env, etc.). */
function commandReadsEnv(command: string): boolean {
	const tokens = command.match(/[\w./-]*\.env[\w.-]*/gi) ?? [];
	return tokens.some(isEnvFile);
}

/** Pull every file path out of a read_files tool input, across its many accepted shapes. */
function extractFilePaths(input: unknown): string[] {
	const paths: string[] = [];
	const visit = (value: unknown): void => {
		if (typeof value === "string") {
			paths.push(value);
		} else if (Array.isArray(value)) {
			value.forEach(visit);
		} else if (value && typeof value === "object") {
			const record = value as Record<string, unknown>;
			if (typeof record.path === "string") {
				paths.push(record.path);
			}
			visit(record.files);
			visit(record.file_paths);
			visit(record.paths);
		}
	};
	visit(input);
	return paths;
}

/** Pull every shell command out of a run_commands input (string | array | { command | commands | cmd }). */
function extractShellCommands(input: unknown): string[] {
	if (typeof input === "string") {
		return [input];
	}
	if (Array.isArray(input)) {
		return input.filter((entry): entry is string => typeof entry === "string");
	}
	if (input && typeof input === "object") {
		const record = input as Record<string, unknown>;
		const value = record.command ?? record.commands ?? record.cmd;
		if (typeof value === "string") {
			return [value];
		}
		if (Array.isArray(value)) {
			return value.filter(
				(entry): entry is string => typeof entry === "string",
			);
		}
	}
	return [];
}

const plugin: AgentPlugin = {
	name: "env-blocker",
	manifest: {
		capabilities: ["hooks"],
	},

	hooks: {
		async beforeTool({ toolCall, input }) {
			let blocked: string | undefined;

			switch (toolCall.toolName) {
				case "read_files":
					blocked = extractFilePaths(input).find(isEnvFile);
					break;
				case "run_commands":
					blocked = extractShellCommands(input).find(commandReadsEnv);
					break;
			}

			if (!blocked) {
				return undefined;
			}

			return {
				skip: true,
				reason: `Blocked ${toolCall.toolName}: reading environment secret files (${blocked}) is not permitted. Ask the user for any values you need.`,
			};
		},
	},
};

export { plugin };
export default plugin;

/**
 * Gitignore Read Guard Plugin Example
 *
 * Blocks file-opening tool calls when any requested path is ignored by a
 * workspace .gitignore file.
 *
 * CLI usage:
 *   cline plugin install https://github.com/cline/cline/blob/main/sdk/examples/plugins/gitignore-read-files-guard.ts --cwd .
 *   cline -i "Read the ignored .env file"
 */

import { spawn } from "node:child_process";
import { isAbsolute, relative, resolve, sep } from "node:path";
import type { AgentPlugin } from "@cline/core";

const FILE_ACCESS_TOOL_NAMES = new Set(["read_files", "editor", "apply_patch"]);

interface IgnoreMatch {
	path: string;
	source: string;
	line: string;
	pattern: string;
}

let workspaceRoot = process.cwd();

function asRecord(value: unknown): Record<string, unknown> | undefined {
	if (typeof value !== "object" || value === null || Array.isArray(value)) {
		return undefined;
	}
	return value as Record<string, unknown>;
}

function addPath(value: unknown, paths: string[]): void {
	if (typeof value === "string" && value.trim().length > 0) {
		paths.push(value);
		return;
	}

	const record = asRecord(value);
	if (typeof record?.path === "string" && record.path.trim().length > 0) {
		paths.push(record.path);
	}
}

function addPathList(value: unknown, paths: string[]): void {
	if (Array.isArray(value)) {
		for (const entry of value) {
			addPath(entry, paths);
		}
		return;
	}
	addPath(value, paths);
}

function extractStructuredPaths(input: unknown): string[] {
	const paths: string[] = [];
	addPath(input, paths);

	if (Array.isArray(input)) {
		addPathList(input, paths);
		return paths;
	}

	const record = asRecord(input);
	if (!record) {
		return paths;
	}

	addPathList(record.files, paths);
	addPathList(record.file_paths, paths);
	addPathList(record.paths, paths);
	return paths;
}

function getApplyPatchInput(input: unknown): string | undefined {
	if (typeof input === "string") {
		return input;
	}

	const record = asRecord(input);
	if (typeof record?.input === "string") {
		return record.input;
	}

	return undefined;
}

function extractApplyPatchPaths(input: unknown): string[] {
	const patch = getApplyPatchInput(input);
	if (!patch) {
		return [];
	}

	const paths: string[] = [];
	const pathHeaders = [
		"*** Add File: ",
		"*** Update File: ",
		"*** Delete File: ",
		"*** Move to: ",
	];

	for (const line of patch.split(/\r?\n/)) {
		for (const header of pathHeaders) {
			if (line.startsWith(header)) {
				const path = line.slice(header.length).trim();
				if (path.length > 0) {
					paths.push(path);
				}
				break;
			}
		}
	}

	return paths;
}

function extractRequestedPaths(toolName: string, input: unknown): string[] {
	if (toolName === "apply_patch") {
		return extractApplyPatchPaths(input);
	}

	return extractStructuredPaths(input);
}

function toWorkspaceRelativePath(path: string): string | undefined {
	const absolutePath = resolve(workspaceRoot, path);
	const relativePath = relative(workspaceRoot, absolutePath);
	if (
		relativePath.length === 0 ||
		relativePath === ".." ||
		relativePath.startsWith(`..${sep}`) ||
		isAbsolute(relativePath) ||
		resolve(workspaceRoot, relativePath) !== absolutePath
	) {
		return undefined;
	}
	return relativePath.split(sep).join("/");
}

function isWorkspaceGitignoreSource(source: string): boolean {
	const normalizedSource = source.split(sep).join("/");
	if (
		normalizedSource !== ".gitignore" &&
		!normalizedSource.endsWith("/.gitignore")
	) {
		return false;
	}

	const absoluteSource = resolve(workspaceRoot, source);
	const relativeSource = relative(workspaceRoot, absoluteSource);
	return (
		relativeSource === ".gitignore" ||
		(!relativeSource.startsWith(`..${sep}`) &&
			!isAbsolute(relativeSource) &&
			relativeSource.endsWith(`${sep}.gitignore`))
	);
}

function parseCheckIgnoreOutput(output: Buffer): IgnoreMatch[] {
	const fields = output.toString("utf8").split("\0");
	const matches: IgnoreMatch[] = [];

	for (let i = 0; i + 3 < fields.length; i += 4) {
		const source = fields[i] ?? "";
		const line = fields[i + 1] ?? "";
		const pattern = fields[i + 2] ?? "";
		const path = fields[i + 3] ?? "";
		if (!source || !pattern || pattern.startsWith("!")) {
			continue;
		}
		if (!line || !path) {
			continue;
		}
		if (!isWorkspaceGitignoreSource(source)) {
			continue;
		}
		matches.push({ source, line, pattern, path });
	}

	return matches;
}

async function checkIgnoredByWorkspaceGitignore(
	relativePaths: string[],
): Promise<IgnoreMatch[]> {
	if (relativePaths.length === 0) {
		return [];
	}

	return new Promise((resolveMatches) => {
		const child = spawn(
			"git",
			["check-ignore", "--stdin", "-z", "-v", "-n", "--no-index"],
			{
				cwd: workspaceRoot,
				stdio: ["pipe", "pipe", "pipe"],
				windowsHide: true,
			},
		);

		const stdout: Buffer[] = [];
		const stderr: Buffer[] = [];

		child.stdout.on("data", (chunk: Buffer) => stdout.push(chunk));
		child.stderr.on("data", (chunk: Buffer) => stderr.push(chunk));

		child.on("error", (error) => {
			console.warn(
				`[gitignore-read-guard] could not run git: ${error.message}`,
			);
			resolveMatches([]);
		});

		child.on("close", (code) => {
			if (code !== 0 && code !== 1) {
				const message = Buffer.concat(stderr).toString("utf8").trim();
				console.warn(
					`[gitignore-read-guard] git check-ignore failed${message ? `: ${message}` : ""}`,
				);
				resolveMatches([]);
				return;
			}

			resolveMatches(parseCheckIgnoreOutput(Buffer.concat(stdout)));
		});

		child.stdin.end(`${relativePaths.join("\0")}\0`);
	});
}

const plugin: AgentPlugin = {
	name: "gitignore-read-files-guard",
	manifest: {
		capabilities: ["hooks"],
	},

	setup(_api, ctx) {
		workspaceRoot = ctx.workspaceInfo?.rootPath ?? process.cwd();
	},

	hooks: {
		async beforeTool({ toolCall, input }) {
			if (!FILE_ACCESS_TOOL_NAMES.has(toolCall.toolName)) {
				return undefined;
			}

			const relativePaths = [
				...new Set(
					extractRequestedPaths(toolCall.toolName, input)
						.map(toWorkspaceRelativePath)
						.filter((path): path is string => Boolean(path)),
				),
			];
			const ignored = await checkIgnoredByWorkspaceGitignore(relativePaths);

			if (ignored.length === 0) {
				return undefined;
			}

			const blockedPaths = ignored.map((match) => match.path).join(", ");
			console.error(
				`[gitignore-read-guard] blocked ${toolCall.toolName}: ${blockedPaths}`,
			);
			return {
				skip: true,
				reason: `Blocked ${toolCall.toolName}: ${blockedPaths} matched workspace .gitignore`,
			};
		},
	},
};

export { plugin };
export default plugin;

/**
 * macOS Notification Plugin Example
 *
 * Sends a Notification Center alert when a Cline run completes successfully.
 *
 * CLI usage:
 *   cline plugin install https://github.com/cline/cline/blob/main/sdk/examples/plugins/mac-notify.ts --cwd .
 *   cline -i "Run the test suite"
 */

import { execFile } from "node:child_process";
import type { AgentPlugin, AgentRunResult } from "@cline/core";

function quoteAppleScriptString(value: string): string {
	return `"${value
		.replaceAll("\\", "\\\\")
		.replaceAll('"', '\\"')
		.replaceAll("\r", " ")
		.replaceAll("\n", " ")
		.slice(0, 220)}"`;
}

function sendMacNotification(title: string, body: string): void {
	if (process.platform !== "darwin") {
		return;
	}

	const script = [
		"display notification",
		quoteAppleScriptString(body),
		"with title",
		quoteAppleScriptString(title),
		"sound name",
		quoteAppleScriptString("Glass"),
	].join(" ");

	execFile("/usr/bin/osascript", ["-e", script], { timeout: 2000 }, () => {
		// Notification failures should never fail or slow down the agent run.
	});
}

function summarizeResult(result: AgentRunResult): string {
	const summary = result.outputText.trim();
	if (summary.length > 0) {
		return summary;
	}
	return `Completed in ${result.iterations} iteration(s).`;
}

const plugin: AgentPlugin = {
	name: "mac-notify-on-complete",
	manifest: {
		capabilities: ["hooks"],
	},

	hooks: {
		afterRun({ result }) {
			if (result.status !== "completed") {
				return;
			}
			sendMacNotification("Cline session completed", summarizeResult(result));
		},
	},
};

export { plugin };
export default plugin;

/**
 * Custom Model Provider Plugin Example
 *
 * Shows how a plugin can register a brand-new model provider so the agent can
 * run inference against it, no changes to Cline itself required.
 *
 * This example registers an OpenAI-compatible provider pointed at OpenRouter.
 * OpenRouter ships as a built-in provider in Cline already, so this example
 * registers under a distinct id (`openrouter-plugin`) to avoid colliding with
 * the built-in. It exists to demonstrate the pattern. Swap the `BASE_URL`,
 * `API_KEY_ENV`, and `MODELS` below to add any OpenAI-compatible endpoint
 * (a self-hosted LiteLLM/vLLM gateway, an internal proxy, a niche provider Cline
 * does not bundle, etc.).
 *
 * How it works:
 *   - `Llms.registerProvider(collection)` adds the provider and its models to
 *     the gateway catalog. With `protocol: "openai-chat"` and
 *     `client: "openai-compatible"`, the gateway builds an OpenAI-compatible
 *     handler from the `baseUrl` and resolves the API key from the session
 *     config or the `env` var declared on the provider.
 *   - `api.registerProvider(...)` declares the contribution on the plugin
 *     (required by the `providers` capability) so hosts can advertise it.
 */

import { type AgentPlugin, Llms } from "@cline/core";

// ---------------------------------------------------------------------------
// Provider definition
//
// Change these constants to point at any OpenAI-compatible endpoint.
// ---------------------------------------------------------------------------

// Provider id exposed by this plugin. Kept distinct from the built-in
// `openrouter` so the two do not collide.
const PROVIDER_ID = "openrouter-plugin";
const PROVIDER_NAME = "OpenRouter (plugin)";
const BASE_URL = "https://openrouter.ai/api/v1";
/** Env var the gateway reads for the API key when one is not passed in the
 * session config. */
const API_KEY_ENV = "OPENROUTER_API_KEY";
const DEFAULT_MODEL_ID = "anthropic/claude-sonnet-4.6";

// ---------------------------------------------------------------------------
// Model catalog
//
// Pricing is per 1M tokens and is illustrative; keep it in sync with the
// provider's own pricing page. `capabilities` tells the runtime what each
// model supports (tool calling, streaming, prompt caching, reasoning, images).
// ---------------------------------------------------------------------------

const MODELS: Record<string, Llms.ModelInfo> = {
	"anthropic/claude-sonnet-4.6": {
		id: "anthropic/claude-sonnet-4.6",
		name: "Claude Sonnet 4.6",
		contextWindow: 200_000,
		maxTokens: 8_192,
		capabilities: ["tools", "streaming", "prompt-cache", "reasoning", "images"],
		pricing: { input: 3, output: 15, cacheRead: 0.3, cacheWrite: 3.75 },
	},
	"openai/gpt-5": {
		id: "openai/gpt-5",
		name: "GPT-5",
		contextWindow: 400_000,
		maxTokens: 16_384,
		capabilities: ["tools", "streaming", "reasoning", "images"],
		pricing: { input: 1.25, output: 10 },
	},
	"google/gemini-2.5-pro": {
		id: "google/gemini-2.5-pro",
		name: "Gemini 2.5 Pro",
		contextWindow: 1_048_576,
		maxTokens: 65_536,
		capabilities: ["tools", "streaming", "reasoning", "images"],
		pricing: { input: 1.25, output: 10 },
	},
};

function buildCollection(): Llms.ModelCollection {
	const provider: Llms.ProviderInfo = {
		id: PROVIDER_ID,
		name: PROVIDER_NAME,
		description:
			"OpenAI-compatible OpenRouter endpoint registered by a plugin.",
		// openai-chat protocol + openai-compatible client => the gateway builds
		// an OpenAI-compatible handler from baseUrl and the resolved API key.
		protocol: "openai-chat",
		client: "openai-compatible",
		baseUrl: BASE_URL,
		defaultModelId: DEFAULT_MODEL_ID,
		// env is the API key env var the gateway falls back to when the session
		// config does not carry an explicit key.
		env: [API_KEY_ENV],
		// Provider capabilities use the provider-level schema. Image support is
		// represented as "vision" here and as "images" on individual models.
		capabilities: ["tools", "streaming", "prompt-cache", "reasoning", "vision"],
		// "file" marks this as a user-added provider rather than a built-in
		// ("system"), which affects trust-level prompts in some hosts.
		source: "file",
	};

	return { provider, models: MODELS };
}

// ---------------------------------------------------------------------------
// Plugin
// ---------------------------------------------------------------------------

const plugin: AgentPlugin = {
	name: "openrouter-provider",
	manifest: {
		capabilities: ["providers"],
		// Declared so hosts that pre-validate contributions know which provider
		// ids this plugin owns before importing it.
		providerIds: [PROVIDER_ID],
	},

	setup(api, ctx) {
		// 1. Register the provider + models with the gateway catalog. This is what
		//    makes inference actually work. The gateway can now resolve
		//    `openrouter-plugin` and its models and build a handler for them.
		Llms.registerProvider(buildCollection());

		// 2. Declare the contribution on the plugin. Required by the "providers"
		//    capability; lets hosts advertise the provider in pickers and surface
		//    its metadata.
		api.registerProvider({
			name: PROVIDER_ID,
			description: `${PROVIDER_NAME}: OpenAI-compatible endpoint at ${BASE_URL}`,
			metadata: {
				baseUrl: BASE_URL,
				apiKeyEnv: API_KEY_ENV,
				defaultModelId: DEFAULT_MODEL_ID,
				modelIds: Object.keys(MODELS),
			},
		});

		ctx.logger?.log(
			`[openrouter-provider] registered provider "${PROVIDER_ID}" with ${Object.keys(MODELS).length} model(s)`,
		);
	},
};

export { plugin, buildCollection };
export default plugin;

/**
 * Telemetry & Logger Plugin Example
 *
 * The reference example for observability from a plugin. Shows how — and how
 * NOT — to use the two host-provided observability channels on the setup
 * context:
 *
 *   ctx.logger    — structured, session-scoped logging for humans debugging a
 *                   session. Goes to the host's log sink (e.g. the CLI log
 *                   file), tagged with your plugin name.
 *   ctx.telemetry — aggregated product/ops signals for dashboards. Goes to
 *                   the host's telemetry service (events + metrics).
 *
 * The contract, in one place:
 *
 *   1. FEATURE-DETECT BOTH. Each is optional — `ctx.logger?.log(...)`,
 *      `ctx.telemetry?.capture(...)`. They are undefined when the host does
 *      not provide them; your plugin must work without them.
 *
 *   2. PLAIN DATA ONLY. Sandboxed plugins run in a separate process; logger
 *      and telemetry calls are forwarded to the host over JSON IPC. Pass
 *      strings, numbers, and booleans — never sockets, clients, or other live
 *      objects. (One exception: `logger` metadata may include an `error`
 *      value that is an Error instance — the bridge serializes its
 *      name/message/stack for you.)
 *
 *   3. NAMESPACING IS AUTOMATIC. The host prefixes every plugin event and
 *      metric with `plugin.` and stamps a `plugin_name` property/attribute,
 *      so plugins cannot impersonate first-party events. Emit short local
 *      names ("cache_refresh"), not pre-namespaced ones.
 *
 *   4. OPT-OUT IS HANDLED HOST-SIDE. When the user disabled telemetry, the
 *      host drops forwarded events. In the sandbox `isEnabled()` always
 *      reports `true` (the bridge is stateless), so do NOT gate expensive
 *      property computation on it — keep properties cheap to build.
 *
 *   5. LOW CARDINALITY, NO CONTENT. Telemetry properties should be statuses,
 *      names of known presets, durations, counts. Never user prompts, file
 *      contents, tool output, or anything secret — that belongs nowhere, and
 *      free-form text does not aggregate anyway. Detailed context goes to the
 *      logger instead (which stays on the user's machine).
 *
 * CLI usage:
 *   cline plugin install https://github.com/cline/cline/blob/main/sdk/examples/plugins/telemetry.ts --cwd .
 *   cline -i "Roll a die a few times and tell me your best roll."
 */

import {
	type AgentPlugin,
	type BasicLogger,
	createTool,
	type ITelemetryService,
} from "@cline/core";

// ---------------------------------------------------------------------------
// Plugin-level state
//
// setup() receives the logger and telemetry handles; hooks and background
// work do not. Capture them once at module level. If your host runs multiple
// sessions in one process, key any *data* by ctx.session?.sessionId — the
// handles themselves are safe to share.
// ---------------------------------------------------------------------------

let logger: BasicLogger | undefined;
let telemetry: ITelemetryService | undefined;

let rollCount = 0;
let bestRoll = 0;

const plugin: AgentPlugin = {
	name: "telemetry-demo",
	manifest: { capabilities: ["tools", "hooks"] },

	setup(api, ctx) {
		logger = ctx.logger;
		telemetry = ctx.telemetry;

		// Logger: human-facing, high-detail, session-scoped. The host tags
		// entries with this plugin's name; metadata is structured, not string
		// interpolation, so log processors can filter on it.
		logger?.log("telemetry-demo setup", {
			sessionId: ctx.session?.sessionId,
			hasTelemetry: Boolean(telemetry),
		});

		// Telemetry event: aggregated, low-cardinality. Arrives at the host as
		// `plugin.demo_setup` with plugin_name/session_id stamped on.
		telemetry?.capture({
			event: "demo_setup",
			properties: { has_workspace: Boolean(ctx.workspaceInfo?.rootPath) },
		});

		api.registerTool(
			createTool({
				name: "roll_die",
				description:
					"Roll a six-sided die and return the result. Demonstrates plugin telemetry and logging.",
				inputSchema: {
					type: "object",
					properties: {
						sides: {
							type: "number",
							description: "Number of sides (default 6).",
						},
					},
					required: [],
				},
				execute: async (input: unknown) => {
					const { sides = 6 } = (input ?? {}) as { sides?: number };

					if (!Number.isInteger(sides) || sides < 2 || sides > 1000) {
						// Failure pattern: log the details for the user's log file,
						// count the failure class (not the message!) in telemetry,
						// and return a structured error for the model.
						// `error` is optional on BasicLogger — hence `?.` twice.
						logger?.error?.("roll_die rejected invalid input", {
							sides,
						});
						telemetry?.recordCounter("demo.tool_errors", 1, {
							tool_name: "roll_die",
							reason: "invalid_sides",
						});
						return { error: "sides must be an integer between 2 and 1000" };
					}

					const roll = 1 + Math.floor(Math.random() * sides);
					rollCount += 1;
					bestRoll = Math.max(bestRoll, roll);

					// debug-level: noisy per-call detail, invisible unless the
					// host's log level includes debug.
					logger?.debug("roll_die rolled", { roll, sides, rollCount });

					// Metrics: counter for volume, histogram for distributions,
					// gauge for point-in-time values. Attribute values must stay
					// low-cardinality — `sides` is fine, a user string is not.
					telemetry?.recordCounter("demo.rolls", 1, { sides });
					telemetry?.recordHistogram("demo.roll_value", roll, { sides });
					telemetry?.recordGauge("demo.best_roll", bestRoll);

					return { roll, sides };
				},
			}),
		);
	},

	hooks: {
		afterRun({ result }) {
			// End-of-run summary event. `captureRequired` bypasses sampling for
			// events that must not be dropped (billing-grade); plain `capture`
			// is right for almost everything, including this.
			telemetry?.capture({
				event: "demo_run_completed",
				properties: {
					status: result.status,
					iterations: result.iterations,
					rolls: rollCount,
					best_roll: bestRoll,
				},
			});
			logger?.log("telemetry-demo run completed", {
				status: result.status,
				rolls: rollCount,
			});
		},
	},
};

export { plugin };
export default plugin;

# TypeScript LSP Plugin

A plugin that gives the agent a `goto_definition` tool powered by the TypeScript Language Service API. Instead of grep or text search, it resolves symbols through imports, re-exports, type aliases, and declaration merging -- the same way your IDE does.

Code entrypoint: [index.ts](./index.ts)

## What it does

The agent gets a single tool: `goto_definition(file, line)`. It finds all identifiers on that line and resolves where they're actually defined. For example, given an import line like:

```ts
import { disposeAll, initVcr } from "@cline/shared"
```

It resolves both symbols through the workspace package alias to their source files:

```
disposeAll -> packages/shared/src/dispose.ts:19
initVcr    -> packages/shared/src/vcr.ts:699
```

## Why this matters

This is a good example of the kind of plugin that makes agents dramatically more effective at navigating large codebases. Text search can find symbol names but can't distinguish between definitions, references, re-exports, and shadowed variables. The TypeScript Language Service handles all of that.

The same pattern applies for enterprise use cases: you can build plugins that wrap internal APIs, deployment systems, feature flags, incident management, CI pipelines, or anything else your team works with. A plugin is just a TypeScript file -- no MCP server to host and maintain.

## Use it with the CLI

```bash
cline plugin install https://github.com/cline/cline/blob/main/sdk/examples/plugins/typescript-lsp/index.ts
cline -i "Find where createTool is defined"
```

The plugin resolves `typescript` from the target project's own `node_modules` at runtime, so it uses the same TS version the project compiles with. No extra dependencies needed.

## Run the demo directly

```bash
ANTHROPIC_API_KEY=sk-... bun run examples/plugins/typescript-lsp/index.ts
```

## How it works

The plugin registers a single tool via `createTool()` in its `setup()` method:

```ts
const plugin: AgentPlugin = {
  name: "typescript-lsp",
  manifest: {
    capabilities: ["tools"],
  },

  setup(api) {
    api.registerTool(
      createTool({
        name: "goto_definition",
        description: "Find where TypeScript/JavaScript symbols on a given line are defined...",
        inputSchema: {
          type: "object",
          properties: {
            file: { type: "string", description: "Absolute path to the file." },
            line: { type: "integer", description: "Line number (1-based)." },
          },
          required: ["file", "line"],
        },
        async execute(input) {
          // 1. Walk up from the file to find tsconfig.json
          // 2. Create (or reuse cached) TypeScript Language Service
          // 3. Scan the AST for identifiers on the target line
          // 4. Resolve each identifier's definition via the Language Service
          // 5. Filter out self-references and return locations
        },
      }),
    );
  },
};
```

Under the hood:

1. `findTsConfig()` walks up parent directories from the target file to find the nearest `tsconfig.json`
2. `loadTypeScript()` uses `createRequire()` to resolve `typescript` from the project's own `node_modules`
3. `createLanguageService()` sets up a full TypeScript Language Service with the project's compiler options
4. The service is cached so subsequent calls in the same session reuse it
5. `getIdentifierOffsetsOnLine()` scans the AST to find all identifiers on the requested line
6. Each identifier is resolved via `service.getDefinitionAtPosition()`, which follows through imports, re-exports, type aliases, etc.

Then pass it to the SDK:

```ts
const host = await ClineCore.create({ backendMode: "local" });
await host.start({
  config: {
    providerId: "anthropic",
    modelId: "claude-sonnet-4-6",
    apiKey: process.env.ANTHROPIC_API_KEY ?? "",
    cwd: process.cwd(),
    enableTools: true,
    systemPrompt: "You are a helpful assistant.",
    extensions: [plugin],
  },
  prompt: "Find where createTool is defined",
  interactive: false,
});
```

/**
 * TypeScript LSP Plugin
 *
 * Gives the agent a `goto_definition` tool powered by the TypeScript Language
 * Service API. It resolves through imports, re-exports, type aliases, etc. so
 * it's much more precise than grep or text search.
 *
 * The plugin resolves `typescript` from the target project's own node_modules
 * at runtime, so it has zero dependencies beyond Node builtins.
 *
 * CLI usage:
 *   cline plugin install https://github.com/cline/cline/blob/main/sdk/examples/plugins/typescript-lsp/index.ts
 *   cline -i "Find where createTool is defined"
 *
 * Direct demo usage:
 *   ANTHROPIC_API_KEY=sk-... bun run examples/plugins/typescript-lsp/index.ts
 */

import { existsSync } from "node:fs";
import { createRequire } from "node:module";
import { dirname, join, resolve } from "node:path";
import { type AgentPlugin, createTool } from "@cline/core";

// ---------------------------------------------------------------------------
// TypeScript Language Service setup
// ---------------------------------------------------------------------------

type LanguageServiceCache = {
	tsconfigPath: string;
	service: ReturnType<typeof createLanguageService>;
	ts: typeof import("typescript");
};

let cache: LanguageServiceCache | undefined;

function findTsConfig(startDir: string): string | undefined {
	let dir = startDir;
	while (true) {
		const candidate = join(dir, "tsconfig.json");
		if (existsSync(candidate)) return candidate;
		const parent = dirname(dir);
		if (parent === dir) return undefined;
		dir = parent;
	}
}

// Resolve typescript from the target project's node_modules so we use the
// same version the project is compiled with.
function loadTypeScript(projectDir: string) {
	const req = createRequire(resolve(projectDir, "package.json"));
	const tsPath = req.resolve("typescript");
	return req(tsPath) as typeof import("typescript");
}

function createLanguageService(
	ts: typeof import("typescript"),
	tsconfigPath: string,
) {
	const projectDir = dirname(tsconfigPath);
	const configFile = ts.readConfigFile(tsconfigPath, ts.sys.readFile);

	if (configFile.error) {
		throw new Error(
			"Failed to read tsconfig.json: " +
				ts.flattenDiagnosticMessageText(configFile.error.messageText, "\n"),
		);
	}

	const parsed = ts.parseJsonConfigFileContent(
		configFile.config,
		ts.sys,
		projectDir,
	);

	const host: import("typescript").LanguageServiceHost = {
		getScriptFileNames: () => parsed.fileNames,
		getScriptVersion: () => "1",
		getScriptSnapshot: (fileName) => {
			const content = ts.sys.readFile(fileName);
			if (content === undefined) return undefined;
			return ts.ScriptSnapshot.fromString(content);
		},
		getCurrentDirectory: () => projectDir,
		getCompilationSettings: () => parsed.options,
		getDefaultLibFileName: (options) => ts.getDefaultLibFilePath(options),
		fileExists: ts.sys.fileExists,
		readFile: ts.sys.readFile,
		readDirectory: ts.sys.readDirectory,
		getDirectories: ts.sys.getDirectories,
	};

	return ts.createLanguageService(host, ts.createDocumentRegistry());
}

function getOrCreateService(tsconfigPath: string) {
	if (cache && cache.tsconfigPath === tsconfigPath) {
		return cache;
	}

	const projectDir = dirname(tsconfigPath);
	const ts = loadTypeScript(projectDir);
	const service = createLanguageService(ts, tsconfigPath);
	cache = { tsconfigPath, service, ts };
	return cache;
}

function offsetToLineCol(
	sourceFile: import("typescript").SourceFile,
	ts: typeof import("typescript"),
	offset: number,
) {
	const lc = ts.getLineAndCharacterOfPosition(sourceFile, offset);
	return { line: lc.line + 1, column: lc.character + 1 };
}

function getIdentifiersOnLine(
	ts: typeof import("typescript"),
	sourceFile: import("typescript").SourceFile,
	targetLine: number,
) {
	const identifiers: Array<{ offset: number; name: string }> = [];
	function visit(node: import("typescript").Node) {
		if (ts.isIdentifier(node)) {
			const lc = ts.getLineAndCharacterOfPosition(
				sourceFile,
				node.getStart(sourceFile),
			);
			if (lc.line + 1 === targetLine) {
				identifiers.push({
					offset: node.getStart(sourceFile),
					name: node.text,
				});
			}
		}
		ts.forEachChild(node, visit);
	}
	visit(sourceFile);
	return identifiers;
}

// ---------------------------------------------------------------------------
// Plugin definition
// ---------------------------------------------------------------------------

type GotoDefinitionInput = { file: string; line: number };

type DefinitionLocation = {
	file: string;
	line: number;
	column: number;
	kind: string;
	name: string;
	containerName?: string;
};

const plugin: AgentPlugin = {
	name: "typescript-lsp",
	manifest: {
		capabilities: ["tools"],
	},

	setup(api) {
		api.registerTool(
			createTool({
				name: "goto_definition",
				description:
					"Find where TypeScript/JavaScript symbols on a given line are defined. " +
					"Given a file path and line number, finds all identifiers on that line " +
					"and resolves their definitions. Much more precise than text search " +
					"-- resolves through imports, re-exports, type aliases, etc.",
				inputSchema: {
					type: "object",
					properties: {
						file: {
							type: "string",
							description: "Absolute path to the file.",
						},
						line: {
							type: "integer",
							description: "Line number (1-based).",
						},
					},
					required: ["file", "line"],
					additionalProperties: false,
				},
				timeoutMs: 30000,
				retryable: false,
				async execute(input: unknown) {
					const { file, line } = input as GotoDefinitionInput;
					const fileName = resolve(file);

					if (!existsSync(fileName)) {
						throw new Error(`File does not exist: ${fileName}`);
					}

					const tsconfigPath = findTsConfig(dirname(fileName));
					if (!tsconfigPath) {
						throw new Error(
							`No tsconfig.json found in any parent directory of ${fileName}`,
						);
					}

					const { ts, service } = getOrCreateService(tsconfigPath);
					const program = service.getProgram();
					if (!program) throw new Error("Failed to create TypeScript program");

					const sourceFile = program.getSourceFile(fileName);
					if (!sourceFile) {
						throw new Error(
							"File not found in TypeScript program. Make sure it is included by tsconfig.json: " +
								fileName,
						);
					}

					const identifiers = getIdentifiersOnLine(ts, sourceFile, line);

					if (identifiers.length === 0) {
						return {
							found: false,
							file,
							line,
							message: "No identifiers found on this line.",
						};
					}

					const results: Array<{
						symbol: string;
						definitions: DefinitionLocation[];
					}> = [];

					const seen = new Set<string>();

					for (const { offset, name: symbolName } of identifiers) {
						if (seen.has(symbolName)) continue;
						seen.add(symbolName);

						const definitions = service.getDefinitionAtPosition(
							fileName,
							offset,
						);
						if (!definitions || definitions.length === 0) continue;

						const nonSelfDefs = definitions.filter((def) => {
							if (def.fileName !== fileName) return true;
							const defLine = offsetToLineCol(
								sourceFile,
								ts,
								def.textSpan.start,
							);
							return defLine.line !== line;
						});

						if (nonSelfDefs.length === 0) continue;

						results.push({
							symbol: symbolName,
							definitions: nonSelfDefs.map((def) => {
								const defSourceFile = program.getSourceFile(def.fileName);
								const loc = defSourceFile
									? offsetToLineCol(defSourceFile, ts, def.textSpan.start)
									: { line: 0, column: 0 };

								return {
									file: def.fileName,
									line: loc.line,
									column: loc.column,
									kind: def.kind,
									name: def.name,
									containerName: def.containerName || undefined,
								};
							}),
						});
					}

					if (results.length === 0) {
						return {
							found: false,
							file,
							line,
							message:
								"Identifiers found on this line but none resolved to external definitions.",
						};
					}

					return {
						found: true,
						query: { file, line },
						tsconfig: tsconfigPath,
						results,
					};
				},
			}),
		);
	},
};

export { plugin };
export default plugin;

/**
 * Custom Plugin Example
 *
 * Shows how to author a reusable plugin module for the CLI and SDK hosts.
 *
 * Demonstrates:
 *   - setup(api, ctx)      — workspace-aware tool registration via
 *                            ctx.workspaceInfo
 *   - hooks.beforeRun / beforeTool / afterTool / afterRun — lifecycle metrics
 *   - ctx.telemetry        — emitting plugin telemetry into the host's
 *                            telemetry service
 *
 * CLI usage:
 *   cline plugin install https://github.com/cline/cline/blob/main/sdk/examples/plugins/weather-metrics.ts --cwd .
 *   cline -i "What's the weather like in Tokyo and Paris?"
 *
 * Direct demo usage:
 *   ANTHROPIC_API_KEY=sk-... bun run examples/plugins/weather-metrics.ts
 */

import {
	type AgentPlugin,
	createTool,
	type ITelemetryService,
} from "@cline/core";

// ---------------------------------------------------------------------------
// Plugin-level state — populated from setup context and available to all hook
// handlers and tool executors for the duration of the session.
// ---------------------------------------------------------------------------

let sessionWorkspaceRoot: string | undefined;
let sessionBranch: string | undefined;
let sessionCommit: string | undefined;
let telemetry: ITelemetryService | undefined;
let toolCallCount = 0;

const plugin: AgentPlugin = {
	name: "weather-and-metrics",
	manifest: {
		capabilities: ["tools", "hooks"],
	},

	// -------------------------------------------------------------------------
	// setup(api, ctx)
	//
	// Called once before the first run. The second argument `ctx` provides
	// workspace context sourced directly from the session config — never from
	// process.cwd() or import.meta.url, so it is correct even when --cwd was
	// passed to the CLI without calling process.chdir().
	//
	//   ctx.workspaceInfo — structured workspace + git metadata: rootPath, hint,
	//                       latestGitCommitHash, latestGitBranchName,
	//                       associatedRemoteUrls
	//
	// Use setup() context for anything that affects tool registration itself —
	// e.g. building workspace-relative descriptions or defaulting file paths.
	// Use setup context for session-scoped plugin state.
	// -------------------------------------------------------------------------
	setup(api, ctx) {
		// Build a workspace-aware description so the model knows exactly where
		// the tool operates. rootPath covers the workspace location and the
		// remaining workspaceInfo fields add the git layer.
		const root = ctx.workspaceInfo?.rootPath ?? "(unknown)";
		const branch = ctx.workspaceInfo?.latestGitBranchName;
		const locationSuffix = branch
			? ` (workspace: ${root}, branch: ${branch})`
			: ` (workspace: ${root})`;

		api.registerTool(
			createTool({
				name: "get_weather",
				description: `Get the current weather for a city${locationSuffix}`,
				inputSchema: {
					type: "object",
					properties: {
						city: { type: "string", description: "The city name" },
					},
					required: ["city"],
				},
				execute: async (input: unknown) => {
					const { city } = input as { city: string };
					return {
						city,
						temperature: "72°F",
						condition: "sunny",
						humidity: "45%",
					};
				},
			}),
		);
		sessionWorkspaceRoot = ctx.workspaceInfo?.rootPath;
		sessionBranch = ctx.workspaceInfo?.latestGitBranchName;
		sessionCommit = ctx.workspaceInfo?.latestGitCommitHash?.slice(0, 7);
		const remotes = ctx.workspaceInfo?.associatedRemoteUrls ?? [];

		// ctx.telemetry routes into the host's telemetry service. Always
		// feature-detect it: it is undefined when the host has no telemetry
		// service. In the plugin sandbox it is a bridge — events cross the
		// process boundary as JSON, so pass only plain data (strings, numbers,
		// booleans), never live objects. The host namespaces every event under
		// `plugin.` and stamps it with this plugin's name.
		//
		// Note: in the sandbox, isEnabled() always reports true — the host
		// decides whether telemetry is on and drops opted-out events on its
		// side. So don't gate expensive property computation on isEnabled();
		// keep properties cheap to build, like the flags below.
		telemetry = ctx.telemetry;
		telemetry?.capture({
			event: "weather_plugin_setup",
			properties: {
				has_workspace: Boolean(sessionWorkspaceRoot),
				branch: sessionBranch,
			},
		});

		console.log(`\n[metrics] session started`);
		if (sessionWorkspaceRoot) {
			console.log(`[metrics] workspace : ${sessionWorkspaceRoot}`);
		}
		if (sessionBranch) {
			console.log(
				`[metrics] branch   : ${sessionBranch}${sessionCommit ? ` @ ${sessionCommit}` : ""}`,
			);
		}
		if (remotes.length > 0) {
			console.log(`[metrics] remotes  : ${remotes.join(", ")}`);
		}
	},

	// -------------------------------------------------------------------------
	// Lifecycle metrics hooks
	// -------------------------------------------------------------------------
	hooks: {
		beforeRun() {
			console.log("\n[metrics] run started");
			return undefined;
		},

		beforeTool({ toolCall, input }) {
			console.log(`[metrics] -> ${toolCall.toolName}`, input);
			toolCallCount += 1;
			// Counters/histograms/gauges work too; the host prefixes the metric
			// name with `plugin.` and adds a plugin_name attribute.
			telemetry?.recordCounter("weather_plugin.tool_calls", 1, {
				tool_name: toolCall.toolName,
			});

			if (toolCall.toolName === "run_commands") {
				const { commands } = input as { commands?: string[] };
				const isProtected =
					sessionBranch === "main" || sessionBranch === "master";
				const hasPush = commands?.some((c) =>
					c.trimStart().startsWith("git push"),
				);
				if (isProtected && hasPush) {
					console.error(
						`[metrics] blocked: git push on protected branch "${sessionBranch}"`,
					);
					return { stop: true, reason: "Blocked git push on protected branch" };
				}
			}
			return undefined;
		},

		afterTool({ toolCall }) {
			console.log(`[metrics] <- ${toolCall.toolName}`);
			return undefined;
		},

		afterRun({ result }) {
			const { status, iterations, usage } = result;
			const loc = sessionWorkspaceRoot ? ` in ${sessionWorkspaceRoot}` : "";
			console.log(
				`[metrics] run done${loc} — ${iterations} iteration(s), status: ${status}`,
			);
			console.log(
				`[metrics] tokens — in: ${usage.inputTokens}, out: ${usage.outputTokens}, cost: ${usage.totalCost?.toFixed(6)}`,
			);
			telemetry?.capture({
				event: "weather_plugin_run_completed",
				properties: {
					status,
					iterations,
					tool_calls: toolCallCount,
					input_tokens: usage.inputTokens,
					output_tokens: usage.outputTokens,
				},
			});
		},
	},
};

export { plugin };
export default plugin;

/**
 * Web Search Plugin Example
 *
 * Registers a `web_search` tool backed by Exa.
 *
 * CLI usage:
 *   cline plugin install https://github.com/cline/cline/blob/main/sdk/examples/plugins/web-search.ts --cwd .
 *   EXA_API_KEY=... cline "Search the web for recent TypeScript 6 updates"
 *
 * Provider key:
 *   EXA_API_KEY              Enables Exa search. A separate model provider key
 *                            is still required for CLI inference.
 */

import { type AgentPlugin, createTool } from "@cline/core";

export interface WebSearchInput {
	query: string;
	limit?: number;
	domains?: string[];
	recencyDays?: number;
	country?: string;
}

export interface WebSearchResult {
	title: string;
	url: string;
	snippet?: string;
	publishedAt?: string;
	author?: string;
	score?: number;
	source: "exa";
}

export interface WebSearchOutput {
	provider: "exa";
	query: string;
	results: WebSearchResult[];
	requestId?: string;
}

interface ExaSearchResult {
	title?: string;
	url?: string;
	publishedDate?: string;
	author?: string;
	score?: number;
	text?: string;
	highlights?: string[];
	summary?: string;
}

interface ExaSearchResponse {
	requestId?: string;
	results?: ExaSearchResult[];
	error?: string;
}

const DEFAULT_RESULT_LIMIT = 5;
const MAX_RESULT_LIMIT = 10;
const EXA_SEARCH_ENDPOINT = "https://api.exa.ai/search";

function env(name: string): string | undefined {
	const value = process.env[name]?.trim();
	return value ? value : undefined;
}

function clampResultLimit(limit: number | undefined): number {
	if (typeof limit !== "number" || !Number.isFinite(limit)) {
		return DEFAULT_RESULT_LIMIT;
	}
	const integer = Math.trunc(limit);
	return Math.min(Math.max(integer, 1), MAX_RESULT_LIMIT);
}

function normalizeDomains(domains: string[] | undefined): string[] | undefined {
	const normalized = domains
		?.map((domain) => domain.trim().replace(/^https?:\/\//, ""))
		.map((domain) => domain.replace(/\/.*$/, ""))
		.filter(Boolean);
	return normalized && normalized.length > 0
		? [...new Set(normalized)]
		: undefined;
}

function isoDateDaysAgo(days: number | undefined): string | undefined {
	if (typeof days !== "number" || !Number.isFinite(days) || days <= 0) {
		return undefined;
	}
	const date = new Date();
	date.setUTCDate(date.getUTCDate() - Math.trunc(days));
	return date.toISOString();
}

function truncateSnippet(text: string | undefined): string | undefined {
	if (!text) {
		return undefined;
	}
	const normalized = text.replace(/\s+/g, " ").trim();
	if (!normalized) {
		return undefined;
	}
	return normalized.length > 800
		? `${normalized.slice(0, 797).trimEnd()}...`
		: normalized;
}

function extractErrorMessage(body: unknown): string | undefined {
	if (!body || typeof body !== "object") {
		return undefined;
	}
	const record = body as Record<string, unknown>;
	for (const key of ["error", "message", "detail"] as const) {
		const value = record[key];
		if (typeof value === "string" && value.trim()) {
			return value;
		}
	}
	return undefined;
}

function asString(value: unknown): string | undefined {
	return typeof value === "string" && value.trim() ? value.trim() : undefined;
}

function asNumber(value: unknown): number | undefined {
	return typeof value === "number" && Number.isFinite(value)
		? value
		: undefined;
}

function hasResultUrl(
	result: ExaSearchResult,
): result is ExaSearchResult & { url: string } {
	return typeof result.url === "string" && result.url.trim().length > 0;
}

function parseWebSearchInput(input: unknown): WebSearchInput {
	if (!input || typeof input !== "object") {
		throw new Error("web_search input must be an object");
	}
	const record = input as Record<string, unknown>;
	const query = asString(record.query);
	if (!query) {
		throw new Error("query is required");
	}

	const domains = Array.isArray(record.domains)
		? record.domains.flatMap((domain) => {
				const value = asString(domain);
				return value ? [value] : [];
			})
		: undefined;

	return {
		query,
		limit: asNumber(record.limit),
		domains,
		recencyDays: asNumber(record.recencyDays),
		country: asString(record.country),
	};
}

async function readJsonResponse<T>(response: Response): Promise<T> {
	const text = await response.text();
	let body: unknown = {};
	try {
		body = text ? (JSON.parse(text) as unknown) : {};
	} catch {
		if (!response.ok) {
			throw new Error(
				`HTTP ${response.status}: ${text || response.statusText}`,
			);
		}
		throw new Error("Search provider returned invalid JSON");
	}

	if (!response.ok) {
		const message = extractErrorMessage(body) ?? (text || response.statusText);
		throw new Error(`HTTP ${response.status}: ${message}`);
	}

	return body as T;
}

function resolveExaApiKey(): string {
	const exaApiKey = env("EXA_API_KEY");
	if (!exaApiKey) {
		throw new Error("Set EXA_API_KEY to use web_search");
	}
	return exaApiKey;
}

async function searchExa(
	input: WebSearchInput,
	apiKey: string,
	limit: number,
	domains: string[] | undefined,
): Promise<WebSearchOutput> {
	const body: Record<string, unknown> = {
		query: input.query,
		numResults: limit,
		contents: {
			highlights: true,
		},
	};
	if (domains) {
		body.includeDomains = domains;
	}
	const startPublishedDate = isoDateDaysAgo(input.recencyDays);
	if (startPublishedDate) {
		body.startPublishedDate = startPublishedDate;
	}
	if (input.country) {
		body.userLocation = input.country.toLowerCase();
	}

	const response = await fetch(EXA_SEARCH_ENDPOINT, {
		method: "POST",
		headers: {
			"x-api-key": apiKey,
			"Content-Type": "application/json",
		},
		body: JSON.stringify(body),
	});
	const json = await readJsonResponse<ExaSearchResponse>(response);

	if (json.error) {
		throw new Error(json.error);
	}

	return {
		provider: "exa",
		query: input.query,
		requestId: json.requestId,
		results: (json.results ?? [])
			.filter(hasResultUrl)
			.slice(0, limit)
			.map((result) => ({
				title: result.title || result.url || "Untitled",
				url: result.url,
				snippet: truncateSnippet(
					result.highlights?.join("\n") ?? result.summary ?? result.text,
				),
				publishedAt: result.publishedDate,
				author: result.author,
				score: result.score,
				source: "exa",
			})),
	};
}

export async function searchWeb(
	input: WebSearchInput,
): Promise<WebSearchOutput> {
	if (!input.query || !input.query.trim()) {
		throw new Error("query is required");
	}

	const limit = clampResultLimit(input.limit);
	const domains = normalizeDomains(input.domains);
	const apiKey = resolveExaApiKey();

	return searchExa(input, apiKey, limit, domains);
}

const plugin: AgentPlugin = {
	name: "web-search",
	manifest: {
		capabilities: ["tools"],
	},

	setup(api) {
		api.registerTool(
			createTool({
				name: "web_search",
				description:
					"Search the web for current public information using Exa. " +
					"Use this to discover relevant URLs, news, docs, and recent facts; use fetch_web_content afterward when a page needs deeper inspection. " +
					"Requires EXA_API_KEY in the plugin host environment.",
				inputSchema: {
					type: "object",
					properties: {
						query: {
							type: "string",
							description:
								"Search query. Use precise terms and include dates when recency matters.",
						},
						limit: {
							type: "number",
							description: `Number of results to return, from 1 to ${MAX_RESULT_LIMIT}. Defaults to ${DEFAULT_RESULT_LIMIT}.`,
						},
						domains: {
							type: "array",
							items: { type: "string" },
							description:
								"Optional domains to restrict results to, such as github.com or docs.exa.ai.",
						},
						recencyDays: {
							type: "number",
							description:
								"Optional freshness window in days. Maps to Exa startPublishedDate.",
						},
						country: {
							type: "string",
							description:
								"Optional lowercase two-letter country code for localized results, such as us.",
						},
					},
					required: ["query"],
					additionalProperties: false,
				},
				timeoutMs: 30_000,
				retryable: true,
				maxRetries: 1,
				execute: async (input: unknown) =>
					searchWeb(parseWebSearchInput(input)),
			}),
		);
	},
};

export { plugin };
export default plugin;
